window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#139"]=[{"v":1,"t":"Când Sever a început să prigonească bisericile, mărturii strălucite au fost date pretutindeni de atleții credinței. Aceasta s-a întâmplat mai ales în Alexandria, în care cetate, ca într-un teatru foarte însemnat, atleți ai lui Dumnezeu erau aduși din Egipt și din toată Tebaida, după vrednicia lor, și câștigau cununi de la Dumnezeu prin marea lor răbdare în multe chinuri și în orice fel de moarte. Printre aceștia a fost Leonid, numit tatăl lui Origen, care a fost decapitat pe când fiul său era încă tânăr. Cât de remarcabilă a fost înclinarea acestui fiu spre Cuvântul dumnezeiesc, ca urmare a învățăturii tatălui său, nu va fi de prisos să arătăm pe scurt, fiindcă faima lui a fost foarte mult răspândită de mulți."}];
window.LIB_LAZY["eusebiu-istoria#140"]=[{"v":1,"t":"Multe s-ar putea spune încercând să descriem viața acestui om pe când era la școală; dar acest subiect singur ar cere un tratat deosebit. Totuși, pentru moment, prescurtând cele mai multe, vom arăta pe scurt câteva fapte despre el, adunându-le din unele scrisori și din spusele unor oameni încă în viață care l-au cunoscut."},{"v":2,"t":"Ce se povestește despre Origen mi se pare vrednic de pomenit, chiar, ca să zic așa, din scutecele lui. Era anul al zecelea al domniei lui Sever, pe când Letus era guvernator al Alexandriei și al restului Egiptului, iar Dimitrie primise de curând episcopia parohiilor de acolo, ca urmaș al lui Iulian."},{"v":3,"t":"Pe când flacăra prigoanei se aprinsese puternic și mulțimi câștigaseră cununa martiriului, o asemenea dorință de martiriu a cuprins sufletul lui Origen, deși era încă băiat, încât se apropia de primejdie, năvălind și repezindu-se la luptă în dorința lui."},{"v":4,"t":"Și într-adevăr sfârșitul vieții lui ar fi fost foarte aproape, dacă purtarea de grijă dumnezeiască și cerească, spre folosul multora, nu ar fi stăvilit dorința lui prin mama sa."},{"v":5,"t":"Căci, la început, rugându-l, l-a rugat să aibă milă de simțămintele ei de mamă față de el; dar văzând că, după ce aflase că tatăl lui fusese prins și întemnițat, el se hotărâse și mai neclintit și era cu totul purtat de râvna lui pentru martiriu, i-a ascuns toate hainele și astfel l-a silit să rămână acasă."},{"v":6,"t":"Dar, neavând altceva ce să facă, și râvna lui mai presus de vârstă nepermițându-i să stea liniștit, a trimis tatălui său o scrisoare de încurajare la martiriu, în care îl îndemna spunând: „Ia seama să nu-ți schimbi gândul din pricina noastră.” Aceasta poate fi însemnată ca prima dovadă a înțelepciunii tinerești a lui Origen și a dragostei lui adevărate pentru cucernicie."},{"v":7,"t":"Căci chiar atunci strânsese nu puține bogății în cuvintele credinței, fiind deprins cu dumnezeieștile Scripturi din copilărie. Și nu le studiase cu nepăsare, căci tatăl lui, pe lângă educația liberală obișnuită, le făcuse o chestiune de nu mică însemnătate."},{"v":8,"t":"Mai întâi de toate, înainte de a-l introduce în științele grecești, l-a deprins cu studiile sfinte, cerându-i să învețe și să recite în fiecare zi."},{"v":9,"t":"Și aceasta nu era povară pentru băiat, ci era doritor și sârguincios în aceste studii. Și nu se mulțumea să învețe ce era simplu și vădit în cuvintele sfinte, ci căuta ceva mai mult și chiar la acea vârstă se îndeletnicea cu cercetări mai adânci. Așa încât își punea tatăl în încurcătură cu întrebări despre adevăratul înțeles al Scripturilor insuflate."},{"v":10,"t":"Iar tatăl îl certa, chipurile, în față, spunându-i să nu cerceteze dincolo de vârsta lui sau dincolo de înțelesul vădit. Dar singur se bucura mult și mulțumea lui Dumnezeu, făcătorul oricărui bine, că l-a învrednicit să fie tatăl unui asemenea copil."},{"v":11,"t":"Și se spune că adesea, stând lângă băiat când dormea, îi descoperea pieptul, ca și cum Duhul dumnezeiesc ar fi sălășluit în el, și îl săruta cu evlavie, socotindu-se fericit în odrasla sa aleasă. Acestea și altele asemenea se povestesc despre Origen ca băiat."},{"v":12,"t":"Dar când tatăl lui și-a încheiat viața prin martiriu, a rămas cu mama sa și cu șase frați mai mici, pe când nu împlinise încă șaptesprezece ani."},{"v":13,"t":"Și averea tatălui său fiind confiscată în vistieria împărătească, el și familia lui duceau lipsă de cele de trebuință vieții. Dar a fost învrednicit de purtarea de grijă dumnezeiască. Și a găsit primire și odihnă la o femeie foarte bogată și deosebită prin felul ei de viață și în alte privințe. Ea cinstea cu multă onoare pe un eretic vestit, care se afla atunci în Alexandria și care era născut în Antiohia. Acesta era la ea ca fiu adoptiv, iar ea îl trata cu cea mai mare bunătate."},{"v":14,"t":"Dar deși Origen era nevoit să se afle în societatea lui, a dat totuși, de atunci încolo, dovezi puternice ale ortodoxiei lui în credință. Căci atunci când, din pricina aparentei măiestrii în vorbire a lui Pavel — căci acesta era numele omului —, o mare mulțime venea la el, nu numai de eretici, ci și de ai noștri, Origen nu a putut fi înduplecat niciodată să se roage împreună cu el; căci ținea, deși băiat, canonul Bisericii și avea în scârbă, cum spune undeva, învățăturile eretice. Fiind instruit în științele grecilor de tatăl său, după moartea acestuia s-a dedicat mai asiduu și exclusiv studiului literelor, așa încât a dobândit o pregătire însemnată în filologie și a putut, nu mult după moartea tatălui său, dedicându-se acelui domeniu, să câștige o răsplată pe deplin îndestulătoare pentru nevoile lui la acea vârstă."}];
window.LIB_LAZY["eusebiu-istoria#141"]=[{"v":1,"t":"Dar pe când ținea prelegeri la școală, după cum ne spune el însuși, și nu era nimeni în Alexandria care să dea învățătură în credință, toți fiind izgoniți de amenințarea prigoanei, unii dintre păgâni au venit la el să audă cuvântul lui Dumnezeu."},{"v":2,"t":"Cel dintâi dintre ei, spune el, a fost Plutarh, care, după ce a trăit bine, a fost cinstit cu martiriul dumnezeiesc. Al doilea a fost Heraclas, fratele lui Plutarh, care, după ce a dat și el împreună cu el dovezi îndestulătoare de viață filozofică și ascetică, a fost găsit vrednic să-l urmeze lui Dimitrie în episcopia Alexandriei."},{"v":3,"t":"Era în al optsprezecelea an al vieții când a luat în grijă școala catehetică. A fost însemnat și în acest timp, în prigoana sub Aquila, guvernatorul Alexandriei, când numele lui a devenit vestit între conducătorii credinței prin bunătatea și bunăvoința pe care a arătat-o față de toți sfinții martiri, cunoscuți lui sau străini."},{"v":4,"t":"Căci nu numai că a fost cu ei cât au fost în lanțuri și până la osânda lor din urmă, dar când sfinții martiri erau duși la moarte, a fost foarte îndrăzneț și a mers cu ei în primejdie. Așa încât, pe cât acționa cu vitejie și îi saluta cu mare îndrăzneală pe martiri cu sărut, mulțimea păgână din jurul lor s-a înfuriat adesea și era gata să se arunce asupra lui."},{"v":5,"t":"Dar prin mâna ajutătoare a lui Dumnezeu a scăpat cu totul și minunat. Și aceeași putere dumnezeiască și cerească l-a păzit iarăși și iarăși, nu se poate spune de câte ori, în asemenea primejdii, din pricina marii lui râvne și îndrăzneli pentru cuvintele lui Hristos. Atât de mare era dușmănia necredincioșilor față de el, din pricina mulțimii care primea de la el învățătura sfintei credințe, încât au pus cete de soldați în jurul casei în care locuia."},{"v":6,"t":"Astfel, zi de zi, prigoana ardea împotriva lui, așa încât întreaga cetate nu-l mai putea cuprinde; ci se muta din casă în casă și era alungat în toate părțile din pricina mulțimii care venea la învățătura dumnezeiască pe care o da. Căci și viața lui înfățișa o purtare dreaptă și minunată după rânduiala filozofiei adevărate."},{"v":7,"t":"Căci se spune că felul lui de viață era ca învățătura lui, iar învățătura lui ca viața lui. De aceea, prin Puterea dumnezeiască ce lucra cu el, a trezit pe foarte mulți la propria lui râvnă."},{"v":8,"t":"Dar când a văzut că vin la el pentru învățătură tot mai mulți și că școala catehetică îi fusese încredințată lui singur de Dimitrie, care păstorea biserica, a socotit că predarea științei gramaticale este nepotrivită cu pregătirea în cele dumnezeiești și îndată și-a lăsat școala de gramatică, ca neprofitabilă și piedică învățăturii sfinte."},{"v":9,"t":"Apoi, cu cuviincioasă chibzuință, ca să nu aibă nevoie de ajutorul altora, a vândut orice cărți de preț ale literaturii vechi avea, mulțumindu-se să primească de la cumpărător patru oboli pe zi. Mulți ani a trăit filozofic în acest chip, lepădând toate îndemnurile poftelor tinereții. Toată ziua îndura nu puțină strădanie, iar pentru cea mai mare parte a nopții se dădea studiului dumnezeieștilor Scripturi. Se înfrâna pe cât putea printr-o viață cât mai filozofică, uneori prin disciplina postului, alteori prin timp scurt de somn. Și în râvna lui nu s-a culcat niciodată pe pat, ci pe pământ."},{"v":10,"t":"Mai ales credea că trebuie păzite cuvintele Mântuitorului din Evanghelie, în care îndeamnă să nu avem două haine, nici să folosim încălțăminte, nici să ne ocupăm cu grija zilei de mâine."},{"v":11,"t":"Cu o râvnă mai presus de vârsta lui a stăruit în frig și goliciune; și, ajungând la sărăcia cea mai desăvârșită, i-a uimit mult pe cei din jurul lui. Și, într-adevăr, a întristat pe mulți dintre prietenii lui care doreau să-și împartă averile cu el, din pricina muncii istovitoare pe care o vedeau că o îndură în predarea celor dumnezeiești."},{"v":12,"t":"Dar nu și-a slăbit stăruința. Se spune că a umblat mulți ani fără să poarte încălțăminte și, ani foarte mulți, s-a abținut de la vin și de la orice altceva dincolo de hrana necesară; așa încât era în primejdia de a se prăbuși și de a-și nimici firea."},{"v":13,"t":"Dând asemenea dovezi ale unei vieți filozofice celor care îl vedeau, a trezit pe mulți dintre ucenicii lui la o râvnă asemănătoare; așa încât bărbați însemnați chiar dintre păgânii necredincioși și oameni care urmau știința și filozofia au fost aduși la învățătura lui. Unii dintre ei, primind de la el, în adâncul sufletului, credința în Cuvântul dumnezeiesc, au devenit însemnați în prigoana care domnea atunci; iar unii dintre ei au fost prinși și au suferit martiriul."}];
window.LIB_LAZY["eusebiu-istoria#142"]=[{"v":1,"t":"Cel dintâi dintre aceștia a fost Plutarh, pomenit chiar mai sus. Pe când era dus la moarte, bărbatul despre care vorbim, fiind cu el la sfârșitul vieții lui, a fost cât pe ce să fie omorât de concetățenii săi, ca și cum ar fi fost pricina morții lui. Dar purtarea de grijă a lui Dumnezeu l-a păzit și de data aceasta."},{"v":2,"t":"După Plutarh, al doilea martir dintre ucenicii lui Origen a fost Serenus, care a dat prin foc dovada credinței pe care o primise."},{"v":3,"t":"Al treilea martir din aceeași școală a fost Heraclid, iar după el al patrulea a fost Hero. Cel dintâi dintre ei era încă catehumen, iar cel de-al doilea fusese botezat de curând. Amândoi au fost decapitați. După ei, al cincilea din aceeași școală, proclamat atlet al cucerniciei, a fost un alt Serenus, care, se povestește, a fost decapitat după o lungă răbdare a chinurilor. Iar dintre femei, Herais a murit pe când era încă catehumenă, primind botezul prin foc, cum spune undeva Origen însuși."}];
window.LIB_LAZY["eusebiu-istoria#143"]=[{"v":1,"t":"Vasilide poate fi socotit al șaptelea dintre aceștia. El a dus la martiriu pe vestita Potamiena, încă faimoasă între oamenii din țară pentru multele pe care le-a îndurat ca să-și păstreze castitatea și fecioria. Căci era în floarea desăvârșirii minții și a darurilor trupești. După ce a suferit mult pentru credința lui Hristos, în cele din urmă, după chinuri înfricoșătoare și groaznice de povestit, a fost omorâtă prin foc, împreună cu mama ei, Marcela."},{"v":2,"t":"Se spune că judecătorul, cu numele Aquila, după ce i-a aplicat chinuri aspre pe tot trupul, a amenințat-o în cele din urmă că o va da gladiatorilor spre batjocura trupului. După puțină chibzuință, fiind întrebată de hotărârea ei, a dat un răspuns care a fost socotit nelegiuit."},{"v":3,"t":"Atunci a primit îndată osânda, iar Vasilide, unul dintre ofițerii armatei, a dus-o la moarte. Dar pe când mulțimea încerca să o necăjească și să o insulte cu cuvinte ocărâtoare, el îi îndepărta pe cei care o insultau, arătându-i multă milă și bunătate. Și, văzând mila omului față de ea, l-a îndemnat să aibă curaj, căci se va ruga Domnului ei pentru el după plecarea ei și va primi curând răsplata pentru bunătatea arătată ei."},{"v":4,"t":"După ce a spus aceasta, a îndurat cu noblețe sfârșitul, smoală încinsă fiind turnată puțin câte puțin pe diferite părți ale trupului ei, de la tălpile picioarelor până în creștetul capului. Aceasta a fost lupta îndurată de această vestită fecioară."},{"v":5,"t":"Nu mult după aceasta, Vasilide, fiind rugat de tovarășii lui de arme să jure dintr-un anumit motiv, a spus că nu-i este îngăduit să jure deloc, căci este creștin, și a mărturisit aceasta pe față. La început au crezut că glumește, dar pentru că stăruia în afirmația lui, a fost dus la judecător și, mărturisind înaintea lui convingerea sa, a fost întemnițat. Iar frații în Dumnezeu venind la el și întrebându-l pricina acestei hotărâri bruște și remarcabile, se spune că a zis că Potamiena, trei zile după martiriul ei, a stat lângă el noaptea, i-a pus o cunună pe cap și a spus că s-a rugat Domnului pentru el și a căpătat ce a cerut și că în curând îl va lua cu ea."},{"v":6,"t":"Atunci frații i-au dat pecetea Domnului; iar a doua zi, după ce a dat o mărturie slăvită pentru Domnul, a fost decapitat. Și se înregistrează că mulți alții din Alexandria au primit repede cuvântul lui Hristos în acele vremuri."},{"v":7,"t":"Căci Potamiena li se arăta în vise și îi îndemna. Dar să fie de ajuns despre aceasta."}];
window.LIB_LAZY["eusebiu-istoria#144"]=[{"v":1,"t":"Clement, urmându-i lui Pantaen, avea în acel timp conducerea învățăturii catehetice din Alexandria, așa încât și Origen, pe când era încă băiat, a fost unul dintre ucenicii lui. În cartea întâi a lucrării numite Stromate, pe care a scris-o Clement, el dă un tabel cronologic, ducând întâmplările până la moartea lui Comod. Așa că este limpede că acea lucrare a fost scrisă în domnia lui Sever, ale cărui vremi le înregistrăm acum."}];
window.LIB_LAZY["eusebiu-istoria#145"]=[{"v":1,"t":"În acest timp un alt scriitor, Iuda, vorbind despre cele șaptezeci de săptămâni din Daniel, duce cronologia până în al zecelea an al domniei lui Sever. El credea că venirea lui Antihrist, despre care se vorbea mult, era atunci aproape. Atât de mult tulburase mințile multora frământarea pricinuită în acest timp de prigoana împotriva ai noștri."}];
window.LIB_LAZY["eusebiu-istoria#146"]=[{"v":1,"t":"În acest timp, pe când Origen conducea învățătura catehetică la Alexandria, a săvârșit o faptă care vădea o minte nedesăvârșită și tinerească, dar dădea totodată cea mai înaltă dovadă de credință și înfrânare. Căci a luat cuvintele: „Sunt fameni care s-au făcut singuri fameni pentru Împărăția cerurilor” (Matei 19:12) într-un înțeles prea literal și prea extrem. Și, ca să împlinească cuvântul Mântuitorului și totodată să ia necredincioșilor orice prilej de sminteală — căci, deși tânăr, se întâlnea pentru studiul celor dumnezeiești atât cu femei, cât și cu bărbați —, a pus în faptă cuvântul Mântuitorului."},{"v":2,"t":"Se gândea că aceasta nu va fi știut de mulți dintre cunoscuții lui. Dar îi era cu neputință, deși dorea, să țină o asemenea faptă în taină."},{"v":3,"t":"Când Dimitrie, care păstorea acea parohie, a aflat în cele din urmă de aceasta, a admirat mult îndrăzneala faptei și, văzându-i râvna și sinceritatea credinței, l-a îndemnat îndată la curaj și l-a îndemnat și mai mult să-și continue lucrarea de învățare catehetică."},{"v":4,"t":"Așa era el în acel timp. Dar curând după aceea, văzând că prosperă și devine mare și deosebit între toți oamenii, același Dimitrie, biruit de slăbiciune omenească, a scris episcopilor din toată lumea despre fapta lui ca despre ceva nespus de nesocotit. Dar episcopii Cezareei și Ierusalimului, care erau deosebit de însemnați și de distinși între episcopii Palestinei, socotindu-l pe Origen vrednic în cel mai înalt grad de cinste, l-au hirotonit prezbiter."},{"v":5,"t":"Atunci faima lui a crescut mult, numele lui a devenit vestit pretutindeni și a căpătat o reputație nu mică de virtute și înțelepciune. Dar Dimitrie, neavând nimic altceva de spus împotriva lui, în afară de această faptă a copilăriei lui, l-a acuzat cu amărăciune și a cutezat să includă în aceste acuzații și pe cei care îl ridicaseră la prezbiterat."},{"v":6,"t":"Aceste lucruri s-au petrecut însă puțin mai târziu. Dar în acest timp Origen a continuat fără teamă învățătura celor dumnezeiești la Alexandria, zi și noapte, tuturor celor care veneau la el, dedicându-și tot răgazul, fără încetare, studiilor dumnezeiești și ucenicilor săi."},{"v":7,"t":"Sever, după ce a ținut cârmuirea timp de optsprezece ani, a fost urmat de fiul său, Antonin. Printre cei care îndurase cu vitejie prigoana acelui timp și fuseseră păstrați de purtarea de grijă a lui Dumnezeu prin luptele mărturisirii era Alexandru, despre care am vorbit deja ca episcop al bisericii din Ierusalim. Pentru întâietatea lui în mărturisirea lui Hristos a fost socotit vrednic de acea episcopie, pe când Narcis, predecesorul lui, era încă în viață."}];
window.LIB_LAZY["eusebiu-istoria#147"]=[{"v":1,"t":"Cetățenii acelei parohii pomenesc multe alte minuni ale lui Narcis, după tradiția fraților care i-au urmat; printre ele povestesc următoarea minune săvârșită de el."},{"v":2,"t":"Se spune că odată a lipsit untdelemnul pe când diaconii priveghează noaptea la marea priveghere pascală. Atunci, toată mulțimea fiind înspăimântată, Narcis a poruncit celor care aveau grija luminilor să scoată apă și să i-o aducă."},{"v":3,"t":"Aceasta făcându-se îndată, s-a rugat peste apă și, cu credință tare în Domnul, le-a poruncit să o toarne în candele. Și după ce au făcut astfel, împotriva oricărei așteptări, printr-o putere minunată și dumnezeiască, firea apei s-a schimbat în aceea a untdelemnului. O mică parte din el s-a păstrat până în zilele noastre la mulți dintre frații de acolo, ca amintire a minunii."},{"v":4,"t":"Povestesc multe alte lucruri vrednice de însemnat din viața acestui om, printre care și aceasta. Unii oameni ticăloși, neputând îndura tăria și neclintirea vieții lui și temându-se de pedeapsă pentru multele fapte rele de care erau conștienți, au căutat să-l prevină prin uneltire și au răspândit împotriva lui o calomnie cumplită."},{"v":5,"t":"Și, ca să convingă pe cei care o auzeau, și-au întărit învinuirile cu jurăminte: unul a chemat asupra lui pieirea prin foc; altul prăpădirea trupului printr-o boală urâtă; al treilea pierderea ochilor. Dar deși au jurat astfel, n-au putut să schimbe mintea credincioșilor, pentru că înfrânarea și viața virtuoasă a lui Narcis erau bine cunoscute tuturor."},{"v":6,"t":"Dar el nu a putut deloc îndura răutatea acestor oameni; și, cum urmase de multă vreme o viață filozofică, a fugit de tot trupul Bisericii și s-a ascuns în locuri pustii și tainice și a rămas acolo mulți ani."},{"v":7,"t":"Dar marele ochi al judecății nu a rămas nemișcat de aceste lucruri, ci s-a uitat în curând asupra acestor oameni nelegiuiți și a adus peste ei blestemele cu care se legaseră. Locuința celui dintâi, dintr-o simplă scânteie căzută peste ea, a fost nimicită cu totul noaptea și el a pierit cu toată familia lui. Al doilea a fost repede acoperit de boala pe care și-o chemase asupra sa, de la tălpile picioarelor până în creștet."},{"v":8,"t":"Iar al treilea, văzând ce se întâmplase celorlalți și temându-se de judecata neînlăturabilă a lui Dumnezeu, stăpânitorul tuturor, a mărturisit public ce uneltiseră împreună. Și în pocăința lui s-a topit atât de mult din pricina marilor lui tânguiri și a plâns într-atât, încât ambii lui ochi au fost nimiciți. Astfel au fost pedepsele pe care le-au primit acești oameni pentru minciuna lor."}];
window.LIB_LAZY["eusebiu-istoria#148"]=[{"v":1,"t":"După plecarea lui Narcis, fără să știe cineva unde se află, cei care păstoreau bisericile învecinate au socotit că e bine să hirotonească un alt episcop. Numele lui era Dius. A păstorit doar puțin timp și i-a urmat Germanion. După el a venit Gordie, în vremea căruia Narcis s-a arătat din nou, ca înviat din morți. Și îndată frații l-au rugat să primească episcopia, căci toți îl admirau cu atât mai mult pentru retragerea și filozofia lui și mai ales pentru pedeapsa cu care Dumnezeu îl răzbunase."}];
window.LIB_LAZY["eusebiu-istoria#149"]=[{"v":1,"t":"Dar fiindcă din pricina vârstei sale înaintate Narcis nu mai putea să-și îndeplinească îndatoririle, purtarea de grijă a lui Dumnezeu l-a chemat în slujbă împreună cu el, printr-o descoperire dată într-o vedenie de noapte, pe pomenitul Alexandru, care era atunci episcop al altei parohii."},{"v":2,"t":"Atunci, ca printr-o îndrumare dumnezeiască, el a călătorit din țara Capadociei, unde ținuse întâi episcopia, la Ierusalim, în urma unui legământ și pentru a se informa despre locurile lui. L-au primit acolo cu mare căldură și nu au vrut să-l lase să se întoarcă, din pricina unei alte descoperiri pe care au văzut-o noaptea și care a dat cea mai limpede veste celor mai râvnitori dintre ei. Căci a făcut cunoscut că, dacă vor ieși afară pe porți, vor primi episcopul rânduit mai dinainte pentru ei de Dumnezeu. Și făcând astfel, cu învoirea unanimă a episcopilor bisericilor învecinate, l-au silit să rămână."},{"v":3,"t":"Alexandru însuși, în scrisori private către antinoiți, care se păstrează încă la noi, pomenește de episcopia comună a lui Narcis și a lui, scriind în aceste cuvinte la sfârșitul epistolei:"},{"v":4,"t":"„Narcis, care a ținut episcopia aici înaintea mea și acum este părtaș cu mine în rugăciuni, având o sută șaisprezece ani, vă salută și vă îndeamnă, ca și eu, să fiți într-un gând.” Acestea s-au petrecut în acest chip. Dar la moartea lui Serapion, Asclepiade, care se distinsese el însuși între mărturisitori în timpul prigoanei, a urmat la episcopia bisericii din Antiohia. Alexandru face aluzie la rânduirea lui, scriind astfel bisericii din Antiohia:"},{"v":5,"t":"„Alexandru, rob și prizonier al lui Isus Hristos, bisericii fericite din Antiohia, salutare în Domnul. Domnul mi-a făcut lanțurile ușoare și lesnicioase în timpul întemnițării mele, de când am aflat că, prin purtarea de grijă dumnezeiască, Asclepiade, care în privința credinței adevărate este eminent pregătit, a luat asupra sa episcopia sfintei voastre biserici din Antiohia.”"},{"v":6,"t":"Arată că a trimis această epistolă prin Clement, scriind spre încheierea ei astfel: „Cinstiți frați, v-am trimis această scrisoare prin Clement, fericitul prezbiter, om virtuos și încercat, pe care îl cunoașteți și voi înșivă și îl veți recunoaște. Fiind aici, prin purtarea de grijă și supravegherea Stăpânului, a întărit și a zidit Biserica Domnului.”"}];
window.LIB_LAZY["eusebiu-istoria#150"]=[{"v":1,"t":"Este probabil că alții au păstrat și alte amintiri ale hărniciei literare a lui Serapion, dar au ajuns la noi doar cele adresate unui anume Domnin, care, în vremea prigoanei, a căzut de la credința în Hristos la închinarea după voia proprie a iudeilor; cele adresate lui Pontiu și Caric, bărbați bisericești, și alte scrisori către diferite persoane, și încă o altă lucrare alcătuită de el despre așa-numita Evanghelie a lui Petru."},{"v":2,"t":"Această din urmă lucrare a scris-o pentru a respinge minciunile cuprinse în acea Evanghelie, din pricina unora din parohia din Rosos, care fuseseră duși de ea în rătăcire spre păreri eretice. Poate fi bine să dăm câteva extrase scurte din lucrarea lui, arătând părerea lui despre carte. Scrie astfel:"},{"v":3,"t":"Căci noi, fraților, îl primim pe Petru și pe ceilalți apostoli ca pe Hristos; dar respingem cu judecată scrierile atribuite lor pe nedrept, știind că astfel de scrieri nu ne-au fost transmise."},{"v":4,"t":"Când v-am vizitat, am crezut că toți țineți credința adevărată și, cum nu citisem Evanghelia pe care o înfățișează sub numele lui Petru, am spus: Dacă aceasta este singurul lucru care pricinuiește ceartă între voi, să fie citită. Dar acum, aflând din cele ce mi s-au spus că mintea lor era încurcată într-o erezie, mă voi grăbi să vin din nou la voi. De aceea, fraților, așteptați-mă în curând."},{"v":5,"t":"Dar veți afla, fraților, din cele scrise vouă, că am înțeles natura ereziei lui Marcian și că, neînțelegând ce spunea, se contrazicea pe sine."},{"v":6,"t":"Căci, dobândind această Evanghelie de la alții care o studiaseră cu sârguință, anume de la urmașii celor care au folosit-o întâi, pe care îi numim doceți (căci cele mai multe dintre părerile lor sunt legate de învățătura acelei școli), am putut să o citim până la capăt și găsim multe lucruri în acord cu adevărata învățătură a Mântuitorului, dar unele lucruri adăugate acelei învățături, pe care vi le-am arătat mai departe. Atât despre Serapion."}];
window.LIB_LAZY["eusebiu-istoria#151"]=[{"v":1,"t":"Toate cele opt Stromate ale lui Clement sunt păstrate la noi și le-a dat următorul titlu: „Stromatele lui Titus Flavius Clement, însemnări gnostice despre adevărata filozofie.”"},{"v":2,"t":"Cărțile intitulate Ipotipoze sunt în același număr. În ele îl pomenește pe Pantaen pe nume ca învățător al său și dă părerile și tradițiile lui."},{"v":3,"t":"Pe lângă acestea, este Cuvântarea sa de îndemn către greci; trei cărți ale unei lucrări intitulate Pedagogul; alta cu titlul Care bogat se mântuiește?; lucrarea despre Paști; discuții despre Post și despre Defăimare; Cuvântarea de îndemn despre răbdare, sau Către cei botezați de curând; și cea purtând titlul Canonul bisericesc, sau Împotriva iudaizanților, pe care a închinat-o lui Alexandru, episcopul pomenit mai sus."},{"v":4,"t":"În Stromate a tratat pe larg nu numai despre dumnezeiasca Scriptură, ci citează și din scriitorii greci oricând ceva din ce au spus ei i se pare folositor."},{"v":5,"t":"Lămurește părerile multora, atât ale grecilor, cât și ale barbarilor. Respinge de asemenea învățăturile false ale conducătorilor de erezii și, pe lângă aceasta, trece în revistă o mare parte din istorie, dându-ne mostre de învățătură foarte variată; cu toate celelalte amestecă părerile filozofilor. Este de crezut că din această pricină a dat lucrării sale titlul potrivit de Stromate."},{"v":6,"t":"Se folosește de asemenea în aceste lucrări de mărturii din Scripturile contestate, așa-numita Înțelepciune a lui Solomon, și a lui Isus, fiul lui Sirah, și Epistola către Evrei, și cele ale lui Barnaba, ale lui Clement și ale lui Iuda."},{"v":7,"t":"Pomenește și Cuvântarea către greci a lui Tațian și vorbește despre Casian ca autor al unei lucrări cronologice. Se referă la autorii iudei Filon, Aristobul, Josephus, Dimitrie și Eupolem, ca arătând toți, în lucrările lor, că Moise și neamul iudeilor au existat înaintea celei mai vechi începuturi a grecilor."},{"v":8,"t":"Aceste cărți abundă și în multă altă învățătură. În prima dintre ele autorul vorbește despre sine ca fiind imediat după urmașii apostolilor."},{"v":9,"t":"În ele făgăduiește de asemenea să scrie un comentariu la Geneza. În cartea sa despre Paști recunoaște că fusese îndemnat de prietenii săi să pună în scris, pentru urmași, tradițiile pe care le auzise de la vechii prezbiteri; și în aceeași lucrare pomenește pe Melito, pe Irineu și pe alții și dă extrase din scrierile lor."}];
window.LIB_LAZY["eusebiu-istoria#152"]=[{"v":1,"t":"Ca să rezumăm pe scurt, el a dat în Ipotipoze relatări prescurtate despre toată Scriptura canonică, fără să omită cărțile contestate — mă refer la Iuda și la celelalte epistole catolice, la Barnaba și la așa-numita Apocalipsă a lui Petru."},{"v":2,"t":"Spune că Epistola către Evrei este lucrarea lui Pavel și că a fost scrisă evreilor în limba evreiască, dar că Luca a tradus-o cu grijă și a publicat-o pentru greci, de unde se găsește același fel de exprimare în această epistolă și în Faptele Apostolilor."},{"v":3,"t":"Dar spune că cuvintele „Pavel Apostolul” probabil nu au fost puse în față pentru că, trimițând-o evreilor, care erau prevenți și bănuitori față de el, n-a vrut, cu înțelepciune, să-i îndepărteze chiar de la început dând numele său."},{"v":4,"t":"Mai departe spune: „Dar acum, după cum a spus fericitul prezbiter, de vreme ce Domnul, fiind apostolul Atotțiitorului, a fost trimis evreilor, Pavel, ca trimis neamurilor, din smerenia lui nu s-a iscălit apostol al evreilor, din respect față de Domnul și pentru că, fiind vestitor și apostol al neamurilor, a scris evreilor din prisosul lui.”"},{"v":5,"t":"Iarăși, în aceleași cărți, Clement dă tradiția celor mai vechi prezbiteri cu privire la rânduiala Evangheliilor, în acest chip:"},{"v":6,"t":"Evangheliile care cuprind genealogiile, spune el, au fost scrise cele dintâi. Evanghelia după Marcu a avut această ocazie. Pe când Petru propovăduise public Cuvântul la Roma și vestise Evanghelia prin Duhul, mulți dintre cei de față l-au rugat pe Marcu, care îl urmase de mult timp și își amintea spusele lui, să le scrie. Și, alcătuind Evanghelia, a dat-o celor care o ceruseră."},{"v":7,"t":"Când Petru a aflat de aceasta, nici nu a oprit-o direct, nici nu a îndemnat la ea. Dar, în cele din urmă, Ioan, văzând că faptele exterioare fuseseră lămurite în Evanghelii, fiind îndemnat de prieteni și insuflat de Duhul, a alcătuit o Evanghelie duhovnicească. Aceasta este relatarea lui Clement."},{"v":8,"t":"Iarăși, pomenitul Alexandru, într-o scrisoare către Origen, se referă la Clement și totodată la Pantaen ca la unii dintre cunoscuții lui apropiați. Scrie astfel: Căci aceasta, după cum știi, a fost voia lui Dumnezeu, ca prietenia părintească dintre noi să rămână neclintită; ba mai mult, să fie mai fierbinte și mai tare."},{"v":9,"t":"Căci îi cunoaștem bine pe acei fericiți părinți care au călcat calea înaintea noastră, cu care vom fi în curând: Pantaen, omul cu adevărat fericit și învățător, și sfântul Clement, învățătorul și binefăcătorul meu, și dacă mai este vreunul asemenea lor, prin care te-am cunoscut pe tine, cel mai bun în toate, învățătorul și fratele meu."},{"v":10,"t":"Atât despre acestea. Dar Adamantie — căci și acesta era un nume al lui Origen — pe când Zefirin era episcop al Romei, a vizitat Roma, „dorind”, cum spune el însuși undeva, „să vadă cea mai veche biserică a Romei.”"},{"v":11,"t":"După o scurtă ședere acolo s-a întors la Alexandria. Și a îndeplinit acolo îndatoririle învățăturii catehetice cu mare râvnă, Dimitrie, care era episcop acolo în acel timp, îndemnându-l și chiar rugându-l să lucreze cu sârguință spre folosul fraților."}];
window.LIB_LAZY["eusebiu-istoria#153"]=[{"v":1,"t":"Dar când a văzut că nu are timp pentru studiul mai adânc al celor dumnezeiești, pentru cercetarea și tâlcuirea Sfintelor Scripturi și, de asemenea, pentru învățarea celor care veneau la el — căci venind unul după altul, de dimineața până seara, ca să fie învățați de el, abia îi lăsau timp să răsufle — a împărțit mulțimea. Și dintre cei pe care îi cunoștea bine l-a ales pe Heraclas, care era un râvnitor student al celor dumnezeiești și, în alte privințe, un om foarte învățat, nu străin de filozofie, și l-a făcut tovarăș al lui în lucrarea de învățare. I-a încredințat pregătirea elementară a începătorilor, dar și-a păstrat pentru sine învățarea celor mai înaintați."}];
window.LIB_LAZY["eusebiu-istoria#154"]=[{"v":1,"t":"Atât de stăruitoare și sârguincioasă a fost cercetarea lui Origen asupra cuvintelor dumnezeiești, încât a învățat limba evreiască și și-a procurat ca ale sale Scripturile evreiești originale care se aflau în mâinile iudeilor. A cercetat de asemenea lucrările altor traducători ai Sfintelor Scripturi, în afară de cei Șaptezeci. Și pe lângă binecunoscutele traduceri ale lui Aquila, Symmachus și Teodotion, a descoperit alte câteva care fuseseră ascunse din vremuri îndepărtate — în ce colțuri uitate nu știu — și prin căutarea lui le-a scos la lumină."},{"v":2,"t":"Neștiind autorii, a spus pur și simplu că a găsit pe aceasta în Nicopole, lângă Actium, și pe cealaltă în alt loc."},{"v":3,"t":"În Hexaplele Psalmilor, după cele patru traduceri însemnate, adaugă nu numai o a cincea, ci și o a șasea și a șaptea. Despre una dintre ele spune că a găsit-o într-un ulcior în Ierihon, în vremea lui Antonin, fiul lui Sever."},{"v":4,"t":"Adunându-le pe toate, le-a împărțit în secțiuni și le-a așezat unele în fața altora, împreună cu însuși textul evreiesc. Astfel ne-a lăsat exemplarele așa-numitelor Hexaple. A aranjat de asemenea separat o ediție a lui Aquila, Symmachus și Teodotion împreună cu Septuaginta, în Tetraple."}];
window.LIB_LAZY["eusebiu-istoria#155"]=[{"v":1,"t":"Despre acești traducători trebuie spus că Symmachus era ebionit. Dar erezia ebioniților, cum este numită, afirmă că Hristos a fost fiul lui Iosif și al Mariei, socotindu-l simplu om, și stăruie puternic să păzească legea în chip iudaic, după cum am văzut deja în această istorie. Se păstrează încă comentarii ale lui Symmachus în care pare să sprijine această erezie atacând Evanghelia după Matei. Origen spune că a dobândit acestea și alte comentarii ale lui Symmachus la Scripturi de la o anume Iuliana, care, spune el, a primit cărțile ca moștenire de la Symmachus însuși."}];
window.LIB_LAZY["eusebiu-istoria#156"]=[{"v":1,"t":"Cam în acest timp Ambrozie, care ținea erezia lui Valentin, a fost convins de înfățișarea adevărului făcută de Origen și, ca și cum mintea lui ar fi fost luminată de lumină, a primit învățătura ortodoxă a Bisericii."},{"v":2,"t":"Mulți alții, de asemenea, atrași de faima învățăturii lui Origen, care răsuna pretutindeni, au venit la el ca să-i pună la încercare priceperea în literatura sfântă. Și foarte mulți eretici și nu puțini dintre cei mai de seamă filozofi au studiat cu sârguință la el, primind de la el învățătură nu numai în cele dumnezeiești, ci și în filozofia lumească."},{"v":3,"t":"Căci atunci când vedea că unele persoane au o inteligență superioară, le învăța și ramurile filozofice — geometria, aritmetica și alte studii pregătitoare — și apoi înainta la sistemele filozofilor și le explica scrierile. Și făcea observații și comentarii la fiecare dintre ei, așa încât a devenit celebru ca mare filozof chiar între greci."},{"v":4,"t":"Și i-a învățat pe mulți dintre cei mai puțin învățați ramurile școlii obișnuite, spunând că acestea le vor fi de nu mică ajutor în studiul și înțelegerea dumnezeieștilor Scripturi. Din această pricină socotea că este deosebit de necesar pentru el însuși să fie priceput în învățătura lumească și filozofică."}];
window.LIB_LAZY["eusebiu-istoria#157"]=[{"v":1,"t":"Filozofii greci ai vremii sale sunt martori ai priceperii lui în aceste subiecte. Găsim pomeniri dese ale lui în scrierile lor. Uneori își închinau lui propriile lucrări; alteori îi supuneau ostenelile lor, ca învățător, spre judecată."},{"v":2,"t":"De ce să mai spunem acestea, când chiar Porfir, care a trăit în Sicilia în vremurile noastre și a scris cărți împotriva noastră, încercând să defăimeze prin ele dumnezeieștile Scripturi, pomenește pe cei care le-au tâlcuit; și, neputând găsi în vreun fel o învinuire josnică împotriva învățăturilor, din lipsă de argumente se întoarce la ocară și calomnie împotriva tâlcuitorilor lor, încercând mai ales să-l defăimeze pe Origen, pe care spune că l-a cunoscut în tinerețea lui."},{"v":3,"t":"Dar, fără să știe, îl laudă pe om; spunând adevărul despre el în unele cazuri în care nu putea face altfel; dar rostind minciuni acolo unde crede că nu va fi prins. Uneori îl învinuiește ca creștin; alteori îi descrie priceperea în învățătura filozofică. Dar ascultați propriile lui cuvinte:"},{"v":4,"t":"„Unele persoane, dorind să găsească o dezlegare a josniciei Scripturilor iudeilor în loc să le părăsească, au recurs la explicații neconforme și nepotrivite cu cuvintele scrise, explicații care, în loc să dea o apărare străinilor, cuprind mai degrabă aprobare și laudă pentru ei înșiși. Căci se laudă că cuvintele simple ale lui Moise sunt enigme și le socotesc oracole pline de taine ascunse; și, după ce au zăpăcit judecata minții prin nebunie, își dau explicațiile.” Mai departe spune:"},{"v":5,"t":"Ca exemplu de această absurditate luați un om pe care l-am întâlnit când eram tânăr și care era atunci mult celebru și încă este, din pricina scrierilor pe care le-a lăsat. Mă refer la Origen, care este foarte cinstit de învățătorii acestor învățături."},{"v":6,"t":"Căci acest om, fiind ascultător al lui Ammonius, care dobândise cea mai mare pricepere în filozofie dintre toți în zilele noastre, a tras mult folos de la învățătorul său în cunoașterea științelor; dar în privința alegerii corecte a vieții, a urmat o cale potrivnică lui."},{"v":7,"t":"Căci Ammonius, fiind creștin și crescut de părinți creștini, când s-a dedicat studiului și filozofiei s-a conformat îndată vieții cerute de legi. Dar Origen, educat ca grec în literatura greacă, a trecut la nesocotința barbară. Și, ducând cu sine învățătura pe care o dobândise, a vândut-o cu zgomot prin târguri, purtându-se în viață ca creștin și împotriva legilor, dar în părerile lui despre lucrurile materiale și despre Dumnezeire fiind ca un grec și amestecând învățăturile grecești cu basme străine."},{"v":8,"t":"Căci îl studia necontenit pe Platon și se îndeletnicea cu scrierile lui Numenie și Cronie, Apolofan, Longin, Moderat și Nicomah și ale celor vestiți între pitagoreici. Și se folosea de cărțile lui Chairemon stoicul și ale lui Cornut. Făcând prin ei cunoștință cu tâlcuirea alegorică a tainelor grecești, a aplicat-o la Scripturile iudeilor."},{"v":9,"t":"Acestea sunt spuse de Porfir în cartea a treia a lucrării sale împotriva creștinilor. Spune adevărul despre hărnicia și învățătura omului, dar rostește vădit o minciună (căci ce nu va face un potrivnic al creștinilor?) când spune că a trecut de la greci și că Ammonius a căzut dintr-o viață de cucernicie în obiceiurile păgâne."},{"v":10,"t":"Căci învățătura lui Hristos i-a fost predată lui Origen de părinții săi, după cum am arătat mai sus. Iar Ammonius a ținut filozofia dumnezeiască neclintită și nefalsificată până la sfârșitul vieții sale. Lucrările lui, încă păstrate, arată aceasta, fiind vestit între mulți prin scrierile pe care le-a lăsat. De pildă, lucrarea intitulată Armonia lui Moise și Isus și alte asemenea care se află în posesia celor învățați."},{"v":11,"t":"Acestea sunt de ajuns ca să arate calomnia învinuitorului mincinos și, de asemenea, priceperea lui Origen în învățătura grecească. Își apără osârdia în această direcție față de unii care îl criticau pentru ea, într-o anumită epistolă, în care scrie astfel:"},{"v":12,"t":"Când m-am dedicat cuvântului și faima priceperii mele s-a răspândit și când au venit la mine eretici și persoane versate în învățătura grecească și mai ales în filozofie, mi s-a părut necesar să cercetez învățăturile ereticilor și ce spun filozofii despre adevăr."},{"v":13,"t":"Și în aceasta l-am urmat pe Pantaen, care a fost de folos multora înaintea noastră prin pregătirea lui temeinică în asemenea lucruri, și pe Heraclas, care este acum membru al prezbiteriului din Alexandria. L-am găsit la învățătorul științei filozofice, cu care continuase deja cinci ani înainte ca eu să încep să ascult prelegeri în acele subiecte."},{"v":14,"t":"Și deși mai înainte purtase îmbrăcămintea obișnuită, a lepădat-o și a luat și poartă și acum haina filozofului; și continuă cercetarea stăruitoare a lucrărilor grecești. Spune acestea apărându-se pentru studiul literaturii grecești."},{"v":15,"t":"Cam în acest timp, pe când era încă în Alexandria, a venit un soldat și a dat o scrisoare de la guvernatorul Arabiei către Dimitrie, episcopul parohiei, și către prefectul Egiptului care era în funcție atunci, cerând să-l trimită cât mai repede pe Origen la el pentru o întrevedere. Fiind trimis de ei, a plecat în Arabia. Și, după ce a îndeplinit în scurt timp scopul vizitei sale, s-a întors la Alexandria."},{"v":16,"t":"Dar după oarecare timp a izbucnit în cetate un război însemnat și a plecat din Alexandria. Și socotind că nu va fi sigur pentru el să rămână în Egipt, a mers în Palestina și a locuit în Cezareea. Cât a stat acolo, episcopii bisericii din acea țară l-au rugat să predice și să tâlcuiască public Scripturile, deși nu fusese încă hirotonit prezbiter."},{"v":17,"t":"Aceasta este vădit din ce au scris lui Dimitrie, în această privință, Alexandru, episcopul Ierusalimului, și Teoctist al Cezareei, apărându-se astfel: El a afirmat în scrisoarea lui că un asemenea lucru nu s-a mai auzit niciodată și nici nu s-a petrecut până acum, ca mirenii să predice în prezența episcopilor. Nu știu cum ajunge să spună ceea ce este vădit neadevărat."},{"v":18,"t":"Căci oricând se găsesc persoane în stare să învețe pe frați, sunt îndemnate de sfinții episcopi să predice poporului. Astfel în Laranda, Euelpis de către Neon; și în Iconiu, Paulin de către Celsus; și în Sinada, Teodor de către Atic, fericiții noștri frați. Și, probabil, s-a făcut aceasta și în alte locuri necunoscute nouă. A fost cinstit în acest chip pe când era încă tânăr, nu numai de compatrioții lui, ci și de episcopi străini."},{"v":19,"t":"Dar Dimitrie a trimis după el prin scrisoare și l-a îndemnat, prin membri ai bisericii și diaconi, să se întoarcă la Alexandria. Astfel s-a întors și și-a reluat îndatoririle obișnuite."}];
window.LIB_LAZY["eusebiu-istoria#158"]=[{"v":1,"t":"În acel timp au înflorit în Biserică mulți bărbați învățați, ale căror scrisori către unii și alții s-au păstrat și sunt ușor de găsit. Ele s-au păstrat până în timpul nostru în biblioteca din Aelia, întemeiată de Alexandru, care păstorea atunci acea biserică. Din acea bibliotecă am putut aduna material pentru lucrarea de față."},{"v":2,"t":"Printre aceștia, Beril ne-a lăsat, pe lângă scrisori și tratate, diferite lucrări alese. A fost episcop al Bostrei din Arabia. De asemenea, Ipolit, care păstorea o altă biserică, a lăsat scrieri."},{"v":3,"t":"A ajuns la noi și un dialog al lui Gaiu, om foarte învățat, purtat la Roma în vremea lui Zefirin, cu Proclu, care susținea erezia frigiană. În el îngrădește nesocotința și îndrăzneala potrivnicilor săi de a înfățișa Scripturi noi. Pomenește doar treisprezece epistole ale sfântului apostol, fără a o număra pe cea către Evrei printre celelalte. Și până în ziua de azi sunt unii dintre romani care nu o socotesc lucrare a apostolului."}];
window.LIB_LAZY["eusebiu-istoria#159"]=[{"v":1,"t":"După ce Antonin a domnit șapte ani și șase luni, i-a urmat Macrin. A ținut cârmuirea doar un an și i-a urmat un alt Antonin. În primul lui an a murit episcopul Romei, Zefirin, după ce își ținuse slujba optsprezece ani, și Calist a primit episcopia."},{"v":2,"t":"A rămas cinci ani și i-a urmat Urban. După aceasta, Alexandru a devenit împărat al Romei, Antonin domnind doar patru ani. În acest timp, Filet i-a urmat și lui Asclepiade în biserica din Antiohia."},{"v":3,"t":"Mama împăratului, cu numele Mamea, era o femeie foarte cucernică, dacă a existat vreodată una, și de viață religioasă. Când faima lui Origen s-a întins pretutindeni și a ajuns chiar la urechile ei, a dorit mult să-l vadă pe om și, mai presus de toate, să încerce vestita lui pricepere în cele dumnezeiești."},{"v":4,"t":"Aflându-se un timp în Antiohia, a trimis după el cu escortă militară. Rămânând un timp cu ea și arătându-i multe lucruri care erau spre slava Domnului și spre desăvârșirea învățăturii dumnezeiești, s-a grăbit să se întoarcă la lucrarea lui obișnuită."}];
window.LIB_LAZY["eusebiu-istoria#160"]=[{"v":1,"t":"În acel timp, Ipolit, pe lângă multe alte tratate, a scris o lucrare despre Paști. Dă în ea un tabel cronologic și înfățișează un anumit canon pascal de șaisprezece ani, ducând timpul până în primul an al împăratului Alexandru."},{"v":2,"t":"Dintre celelalte scrieri ale lui au ajuns la noi următoarele: Despre Hexaemeron, Despre lucrările de după Hexaemeron, Împotriva lui Marcion, Despre Cântarea Cântărilor, Despre părți din Ezechiel, Despre Paști, Împotriva tuturor ereziilor; și puteți găsi multe alte lucrări păstrate de mulți."}];
window.LIB_LAZY["eusebiu-istoria#161"]=[{"v":1,"t":"În acel timp Origen și-a început comentariile la dumnezeieștile Scripturi, fiind îndemnat la aceasta de Ambrozie, care a folosit nenumărate îndemnuri, nu numai sfătuindu-l prin cuvânt, ci și punându-i la dispoziție mijloace din belșug."},{"v":2,"t":"Căci dicta mai multor șapte scriitori, care se schimbau unii pe alții la ore rânduite. Și folosea nu mai puțini copiști, pe lângă fete pricepute în scrierea frumoasă. Pentru toți aceștia Ambrozie a pus la dispoziție din belșug cheltuiala necesară, arătând el însuși o râvnă de nespus în sârguință și osârdie pentru cuvintele dumnezeiești, prin care îl împingea mai ales la pregătirea comentariilor sale."},{"v":3,"t":"În timp ce se petreceau acestea, lui Urban, care fusese opt ani episcop al bisericii Romei, i-a urmat Pontian, iar lui Filet, în Antiohia, i-a urmat Zebin."},{"v":4,"t":"În acest timp Origen a fost trimis în Grecia din pricina unei nevoi stringente legate de treburile bisericești și a trecut prin Palestina și a fost hirotonit prezbiter la Cezareea de episcopii acelei țări. Întâmplările care s-au agitat în privința lui din această pricină și hotărârile în aceste chestiuni ale celor care păstoreau bisericile, pe lângă celelalte lucrări despre cuvântul dumnezeiesc pe care le-a publicat în floarea vârstei, cer un tratat deosebit. Am scris despre ele într-o oarecare măsură în cartea a doua a Apărării pe care am alcătuit-o în favoarea lui."}];
window.LIB_LAZY["eusebiu-istoria#162"]=[{"v":1,"t":"Poate fi bine să adăugăm că în cartea a șasea a expunerii sale la Evanghelia după Ioan spune că primele cinci le-a alcătuit pe când era în Alexandria. Din lucrarea lui la întreaga Evanghelie nu au ajuns la noi decât douăzeci și două de volume."},{"v":2,"t":"În a noua dintre cele despre Geneza, din care sunt douăsprezece în total, spune că nu numai cele opt dinainte fuseseră alcătuite la Alexandria, ci și cele despre primii douăzeci și cinci de psalmi și despre Plângeri. Din acestea din urmă au ajuns la noi cinci volume."},{"v":3,"t":"În ele pomenește și cărțile sale Despre înviere, care sunt două. A scris de asemenea cărțile Despre principii înainte de a părăsi Alexandria; iar cuvântările intitulate Stromate, zece la număr, le-a alcătuit în aceeași cetate în timpul domniei lui Alexandru, după cum arată însemnările scrise de mâna lui, care preced volumele."}];
window.LIB_LAZY["eusebiu-istoria#163"]=[{"v":1,"t":"Tâlcuind primul Psalm, dă un catalog al sfintelor Scripturi ale Vechiului Testament astfel: „Trebuie spus că cărțile canonice, după cum le-au transmis evreii, sunt douăzeci și două, corespunzând numărului literelor lor.” Mai departe spune:"},{"v":2,"t":"„Cele douăzeci și două de cărți ale evreilor sunt următoarele: cea numită de noi Geneza, iar de evrei, după începutul cărții, Bresit, adică «La început»; Exodul, Welesmot, adică «Acestea sunt numele»; Leviticul, Wikra, «Și a chemat»; Numerii, Ammesfekodeim; Deuteronomul, Eleaddebareim, «Acestea sunt cuvintele»; Isus, fiul lui Navi, Iosue ben Nun; Judecătorii și Rut, la ei într-o singură carte, Safateim; Întâia și a doua a Regilor, la ei una, Samuel, adică «Cel chemat de Dumnezeu»; a treia și a patra a Regilor într-una, Wammelh David, adică «Împărăția lui David»; din Cronici, întâia și a doua într-una, Dabreiamein, adică «Cronica zilelor»; Ezdra, întâia și a doua într-una, Ezra, adică «Ajutor»; cartea Psalmilor, Sfarthelleim; Proverbele lui Solomon, Meloth; Eclesiastul, Koelth; Cântarea Cântărilor (nu, cum socotesc unii, Cântările Cântărilor), Sir Hassirim; Isaia, Iessia; Ieremia, cu Plângerile și epistola într-una, Ieremia; Daniel, Daniel; Ezechiel, Iezechiel; Iov, Iov; Estera, Estera. Și în afară de acestea sunt Macabeii, care poartă titlul Sarbet Sabanaiel.” Acestea le dă în lucrarea pomenită."},{"v":3,"t":"În prima sa carte despre Evanghelia după Matei, ținând canonul Bisericii, mărturisește că nu cunoaște decât patru Evanghelii, scriind astfel:"},{"v":4,"t":"Dintre cele patru Evanghelii, care sunt singurele fără îndoială în Biserica lui Dumnezeu de sub cer, am aflat prin tradiție că prima a fost scrisă de Matei, care fusese odinioară vameș, dar apoi apostol al lui Isus Hristos, și a fost pregătită pentru cei convertiți din iudaism și publicată în limba evreiască."},{"v":5,"t":"A doua este a lui Marcu, care a alcătuit-o după îndrumările lui Petru, care în epistola sa catolică îl recunoaște ca fiu, spunând: «Vă îmbrățișează Biserica cea aleasă care este în Babilon și Marcu, fiul meu.» (1 Petru 5:13)"},{"v":6,"t":"Iar a treia este a lui Luca, Evanghelia lăudată de Pavel și alcătuită pentru cei convertiți dintre neamuri. În sfârșit, cea a lui Ioan."},{"v":7,"t":"În cartea a cincea a Expunerilor sale la Evanghelia lui Ioan, vorbește astfel despre epistolele apostolilor: Dar cel care a fost «făcut destoinic să fie slujitor al Noului Testament, nu al literei, ci al Duhului» (2 Corinteni 3:6), adică Pavel, care «a vestit pe deplin Evanghelia de la Ierusalim și împrejur până în Iliric» (Romani 15:19), nu a scris tuturor bisericilor pe care le învățase, iar celor cărora le-a scris le-a trimis puține rânduri."},{"v":8,"t":"Iar Petru, pe care este zidită Biserica lui Hristos, «împotriva căreia porțile iadului nu vor birui» (Matei 16:18), a lăsat o epistolă recunoscută; poate și o a doua, dar aceasta este îndoielnică."},{"v":9,"t":"Ce nevoie este să vorbim despre cel care s-a rezemat pe pieptul lui Isus, Ioan, care ne-a lăsat o Evanghelie, deși mărturisea că ar putea scrie atât de multe, încât lumea nu le-ar putea cuprinde? Și a scris și Apocalipsa, dar i s-a poruncit să tacă și să nu scrie cuvintele celor șapte tunete."},{"v":10,"t":"A lăsat și o epistolă de foarte puține rânduri; poate și o a doua și o a treia; dar nu toți le socotesc adevărate și împreună nu cuprind o sută de rânduri."},{"v":11,"t":"În plus, face următoarele afirmații cu privire la Epistola către Evrei în Omiliile sale asupra ei: Că stilul verbal al epistolei intitulate «Către Evrei» nu este grosolan ca limba apostolului, care s-a recunoscut «necioplit în vorbire» (2 Corinteni 11:6), adică în exprimare; ci că dicțiunea ei este o greacă mai curată, oricine are puterea să deosebească felurile de exprimare va recunoaște."},{"v":12,"t":"Mai mult, că gândurile epistolei sunt minunate și nu mai prejos decât scrierile apostolice recunoscute, oricine cercetează cu grijă textul apostolic va admite."},{"v":13,"t":"Mai departe adaugă: Dacă mi-aș da părerea, aș spune că gândurile sunt ale apostolului, dar dicțiunea și exprimarea sunt ale cuiva care și-a amintit învățăturile apostolice și a pus în scris, în răgaz, cele spuse de învățătorul său. De aceea, dacă vreo biserică ține că această epistolă este a lui Pavel, să fie lăudată pentru aceasta. Căci nu fără pricină au transmis-o cei vechi ca fiind a lui Pavel."},{"v":14,"t":"Dar cine a scris epistola, în adevăr, Dumnezeu știe. Spusa unora dintre cei dinaintea noastră este că Clement, episcopul romanilor, a scris epistola, iar a altora că Luca, autorul Evangheliei și al Faptelor, a scris-o. Dar să fie de ajuns despre aceste chestiuni."}];
window.LIB_LAZY["eusebiu-istoria#164"]=[{"v":1,"t":"În al zecelea an al domniei pomenite, Origen s-a mutat din Alexandria la Cezareea, lăsând grija școlii catehetice din acea cetate lui Heraclas. Nu mult după aceea a murit Dimitrie, episcopul bisericii din Alexandria, după ce ținuse slujba patruzeci și trei de ani întregi, și Heraclas i-a urmat. În acest timp Firmilian, episcopul Cezareei Capadociei, era însemnat."}];
window.LIB_LAZY["eusebiu-istoria#165"]=[{"v":1,"t":"Era atât de statornic atras spre Origen, încât l-a îndemnat să vină în acea țară spre folosul bisericilor și, mai mult, l-a vizitat în Iudeea, rămânând cu el un timp, spre sporire în cele dumnezeiești. Iar Alexandru, episcopul Ierusalimului, și Teoctist, episcopul Cezareei, îl însoțeau neîncetat, ca pe singurul lor învățător, și îi îngăduiau să tâlcuiască dumnezeieștile Scripturi și să îndeplinească celelalte îndatoriri ale cuvântării bisericești."}];
window.LIB_LAZY["eusebiu-istoria#166"]=[{"v":1,"t":"Împăratul Romei, Alexandru, după ce și-a încheiat domnia în treisprezece ani, a fost urmat de Cezarul Maximin. Din ura lui față de casa lui Alexandru, în care erau mulți credincioși, a început o prigoană, poruncind să fie omorâți doar conducătorii bisericilor, ca răspunzători pentru învățătura Evangheliei. Atunci Origen a alcătuit lucrarea sa Despre martiriu și a închinat-o lui Ambrozie și lui Protoctet, prezbiter al parohiei Cezareei, pentru că în prigoană veniseră peste amândoi greutăți neobișnuite, în care se povestește că s-au distins în mărturisire în timpul domniei lui Maximin, care a durat doar trei ani. Origen a însemnat acest timp ca timp al prigoanei în cartea a douăzeci și doua a Comentariilor sale la Ioan și în mai multe epistole."}];
window.LIB_LAZY["eusebiu-istoria#167"]=[{"v":1,"t":"Gordian i-a urmat lui Maximin ca împărat al Romei; iar lui Pontian, care fusese șase ani episcop al bisericii din Roma, i-a urmat Anter. După ce a ținut slujba o lună, i-a urmat Fabian."},{"v":2,"t":"Se spune că Fabian, venind după moartea lui Anter, cu alții de la țară, se afla la Roma și că, fiind acolo, a fost ales pentru slujbă printr-o arătare foarte minunată a harului dumnezeiesc și ceresc."},{"v":3,"t":"Căci atunci când toți frații se adunaseră pentru a alege prin vot pe cel care să urmeze la episcopia bisericii, mai mulți bărbați vestiți și cinstiți erau în gândul multora, dar Fabian, deși de față, nu era în gândul nimănui. Dar povestesc că deodată un porumbel, zburând în jos, s-a așezat pe capul lui, asemănându-se coborârii Duhului Sfânt peste Mântuitorul în chip de porumbel."},{"v":4,"t":"Atunci tot poporul, ca mișcat de un singur Duh dumnezeiesc, cu toată râvna și într-un glas a strigat că este vrednic și, fără zăbavă, l-au luat și l-au așezat pe scaunul episcopal."},{"v":5,"t":"Cam în acel timp a murit Zebin, episcopul Antiohiei, și i-a urmat Vavila. Iar în Alexandria, lui Heraclas, care primise slujba episcopală după Dimitrie, i-a urmat în grija școlii catehetice Dionisie, care fusese și el unul dintre ucenicii lui Origen."}];
window.LIB_LAZY["eusebiu-istoria#168"]=[{"v":1,"t":"Pe când Origen își ducea mai departe îndatoririle obișnuite la Cezareea, mulți ucenici au venit la el nu numai din apropiere, ci și din alte țări. Printre aceștia știm că au fost deosebit de vestiți Teodor, același care s-a distins între episcopii zilelor noastre sub numele de Grigorie, și fratele său Atenodor. Găsindu-i adânc interesați de învățătura greacă și romană, le-a insuflat dragostea de filozofie și i-a dus să-și schimbe vechea râvnă cu studiul dumnezeirii. Rămânând cinci ani cu el, au făcut atâta progres în cele dumnezeiești, încât, deși erau încă tineri, amândoi au fost cinstiți cu o episcopie în bisericile din Pont."}];
window.LIB_LAZY["eusebiu-istoria#169"]=[{"v":1,"t":"În acest timp era bine cunoscut și Africanus, scriitorul cărților intitulate Cesti. Se păstrează o epistolă a lui către Origen, exprimând îndoieli asupra povestirii despre Susana din Daniel, ca fiind falsă și născocită. Origen i-a răspuns foarte pe larg."},{"v":2,"t":"Alte lucrări ale aceluiași Africanus care au ajuns la noi sunt cele cinci cărți ale sale despre Cronologie, lucrare pregătită cu exactitate și osteneală. Spune în ea că a mers la Alexandria din pricina marii faime a lui Heraclas, care excela mai ales în studiile filozofice și în alte științe grecești și a cărui rânduire la episcopia bisericii de acolo am pomenit-o deja."},{"v":3,"t":"Se păstrează și o altă epistolă a aceluiași Africanus către Aristid, despre presupusa neînvoire dintre Matei și Luca în genealogiile lui Hristos. În ea arată limpede învoirea evangheliștilor, dintr-o relatare care ajunsese la el, pe care am dat-o deja la locul potrivit în cartea întâi a acestei lucrări."}];
window.LIB_LAZY["eusebiu-istoria#170"]=[{"v":1,"t":"Cam în acest timp Origen și-a pregătit Comentariile la Isaia și la Ezechiel. Din cel dintâi au ajuns la noi treizeci de cărți, până la a treia parte a lui Isaia, până la vedenia fiarelor din pustie; iar despre Ezechiel douăzeci și cinci de cărți, care sunt tot ce a scris despre întregul prooroc."},{"v":2,"t":"Aflându-se atunci la Atena, și-a încheiat lucrarea despre Ezechiel și a început Comentariile la Cântarea Cântărilor, pe care le-a dus până la cartea a cincea. După întoarcerea la Cezareea, le-a încheiat și pe acestea, în număr de zece cărți."},{"v":3,"t":"Dar de ce să dăm în această istorie un catalog exact al lucrărilor omului, care ar cere un tratat deosebit? Am dat și aceasta în povestirea noastră despre viața lui Pamfil, un sfânt martir al vremii noastre. După ce arătăm cât de mare a fost sârguința lui Pamfil în cele dumnezeiești, dăm în ea un catalog al bibliotecii pe care a adunat-o din lucrările lui Origen și ale altor scriitori bisericești. Oricine dorește poate afla ușor de aici care dintre lucrările lui Origen au ajuns la noi. Dar trebuie să mergem acum mai departe cu istoria noastră."}];
window.LIB_LAZY["eusebiu-istoria#171"]=[{"v":1,"t":"Beril, pe care l-am pomenit de curând ca episcop al Bostrei din Arabia, s-a abătut de la rânduiala bisericească și a încercat să introducă idei străine de credință. A cutezat să afirme că Mântuitorul și Domnul nostru nu a existat mai înainte într-o formă distinctă de ființă proprie înainte de șederea Lui între oameni și că nu are o dumnezeire proprie, ci doar pe aceea a Tatălui sălășluind în El."},{"v":2,"t":"Mulți episcopi au purtat cercetări și discuții cu el în această privință, iar Origen, fiind chemat împreună cu ceilalți, a mers întâi la o convorbire cu el, ca să afle părerea lui adevărată. Dar când a înțeles părerile lui și a văzut că sunt greșite, după ce l-a convins prin argumente și l-a lămurit prin demonstrație, l-a adus înapoi la învățătura adevărată și l-a întors la vechea lui părere sănătoasă."},{"v":3,"t":"Se păstrează încă scrieri ale lui Beril și ale sinodului ținut din pricina lui, care cuprind întrebările puse lui de Origen și discuțiile purtate în parohia lui, precum și toate cele făcute atunci."},{"v":4,"t":"Frații mai vârstnici dintre noi au transmis multe alte fapte privind pe Origen, pe care socotesc potrivit să le las deoparte, ca nepotrivite acestei lucrări. Dar tot ce a părut necesar să se consemneze despre el se poate găsi în Apărarea scrisă în favoarea lui de noi și de Pamfil, sfântul martir al zilelor noastre. Am alcătuit-o cu grijă și am făcut lucrarea împreună din pricina celor care caută cusururi."}];
window.LIB_LAZY["eusebiu-istoria#172"]=[{"v":1,"t":"Gordian fusese împărat al Romei șase ani când i-a urmat Filip, împreună cu fiul său Filip. Se povestește că el, fiind creștin, a dorit, în ziua ultimei privegheri pascale, să împartă cu mulțimea rugăciunile Bisericii, dar că cel care păstorea atunci nu l-a lăsat să intre până nu și-a mărturisit păcatele și nu s-a numărat printre cei socotiți călcători de lege, care ocupau locul pocăinței. Căci dacă nu ar fi făcut aceasta, nu ar fi fost primit niciodată de el, din pricina multelor crime pe care le săvârșise. Se spune că a ascultat de bunăvoie, arătând în purtarea lui o teamă de Dumnezeu adevărată și cucernică."}];
window.LIB_LAZY["eusebiu-istoria#173"]=[{"v":1,"t":"În al treilea an al acestui împărat a murit Heraclas, după ce ținuse slujba șaisprezece ani, și Dionisie a primit episcopia bisericilor din Alexandria."}];
window.LIB_LAZY["eusebiu-istoria#174"]=[{"v":1,"t":"În acest timp, pe măsură ce credința se întindea și învățătura noastră era vestită cu îndrăzneală înaintea tuturor, Origen, având, cum se spune, peste șaizeci de ani și dobândind mare ușurință prin lunga lui deprindere, a îngăduit, foarte potrivit, ca cuvântările lui publice să fie luate de stenografi, lucru pe care nu-l îngăduise niciodată înainte."},{"v":2,"t":"A alcătuit de asemenea în acest timp o lucrare de opt cărți ca răspuns celei intitulate Cuvânt adevărat, care fusese scrisă împotriva noastră de Celsus epicureul, și cele douăzeci și cinci de cărți despre Evanghelia după Matei, pe lângă cele despre cei Doisprezece Proroci, din care noi am găsit doar douăzeci și cinci."},{"v":3,"t":"Se păstrează și o epistolă a lui către împăratul Filip și alta către Severa, soția lui, cu mai multe altele către diferite persoane. Am rânduit în cărți distincte, în număr de o sută, ca să nu mai fie risipite, câte dintre acestea am putut aduna, care fuseseră păstrate pe ici pe colo de diferite persoane."},{"v":4,"t":"A scris și lui Fabian, episcopul Romei, și multor altor conducători ai bisericilor despre ortodoxia sa. Aveți exemple din acestea în cartea a opta a Apărării pe care am scris-o în favoarea lui."}];
window.LIB_LAZY["eusebiu-istoria#175"]=[{"v":1,"t":"Cam în același timp s-au ridicat alții în Arabia, înfățișând o învățătură străină de adevăr. Ei spuneau că în timpul de față sufletul omenesc moare și piere împreună cu trupul, dar că la vremea învierii vor fi înnoiți împreună. Și atunci s-a adunat un sinod de proporții însemnate, iar Origen, fiind din nou chemat acolo, a vorbit public asupra întrebării cu atâta efect, încât părerile celor care căzuseră mai înainte s-au schimbat."}];
window.LIB_LAZY["eusebiu-istoria#176"]=[{"v":1,"t":"O altă rătăcire s-a ivit de asemenea în acest timp, numită erezia elkesaiților, care s-a stins chiar la început. Origen vorbește despre ea în acest chip într-o omilie publică la Psalmul optzeci și doi:"},{"v":2,"t":"„A venit de curând un om, umflat foarte tare de propria lui putere, vestind acea părere fără Dumnezeu și nelegiuită care s-a ivit de curând în biserici, numită «a elkesaiților». Vă voi arăta ce lucruri rele învață acea părere, ca să nu fiți duși de ea. Ea respinge unele părți din fiecare scriptură. Iarăși, se folosește de porțiuni din Vechiul Testament și din Evanghelie, dar respinge cu totul pe apostol. Spune că tăgăduirea lui Hristos este un lucru fără însemnătate și că cel care înțelege va tăgădui, la nevoie, cu gura, dar nu cu inima. Ei scot la iveală o carte despre care spun că a căzut din cer. Țin că oricine o aude și crede în ea va primi iertarea păcatelor, o altă iertare decât cea pe care a dat-o Isus Hristos.” Aceasta este relatarea despre acești oameni."}];
window.LIB_LAZY["eusebiu-istoria#177"]=[{"v":1,"t":"După o domnie de șapte ani, lui Filip i-a urmat Deciu. Din ura lui față de Filip, a început o prigoană împotriva bisericilor, în care Fabian a suferit martiriul la Roma, iar Corneliu i-a urmat în episcopie."},{"v":2,"t":"În Palestina, Alexandru, episcopul bisericii din Ierusalim, a fost adus din nou, pentru Hristos, înaintea scaunului de judecată al guvernatorului din Cezareea și, după ce s-a dovedit nobil într-o a doua mărturisire, a fost aruncat în temniță, încununat cu perii albi ai venerabilei bătrânețe."},{"v":3,"t":"Și după mărturisirea lui cinstită și strălucită la tribunalul guvernatorului, a adormit în temniță, iar Mazabane i-a urmat în episcopia Ierusalimului."},{"v":4,"t":"Vavila din Antiohia, trecând și el ca Alexandru în temniță după mărturisirea lui, a fost urmat de Fabiu în episcopia acelei biserici."},{"v":5,"t":"Dar câte și cât de mari lucruri au venit peste Origen în prigoană și care a fost sfârșitul lor — pe când demonul răutății își aduna toate puterile și se lupta împotriva omului cu toată viclenia și puterea lui, atacându-l mai mult decât pe toți ceilalți cu care se lupta atunci — și ce și cât a îndurat pentru cuvântul lui Hristos, lanțuri și chinuri trupești și suferințe sub zgarda de fier și în temniță; și cum multe zile, cu picioarele întinse patru trepte în butuci, a răbdat cu stăruință amenințările cu focul și orice alte lucruri i-au fost aduse de dușmanii lui; și cum au luat sfârșit suferințele lui, judecătorul străduindu-se cu toată puterea să nu-i pună capăt vieții; și ce cuvinte a lăsat după acestea, pline de mângâiere pentru cei care aveau nevoie de ajutor, arată cu adevăr și precizie o mare parte din epistolele sale."}];
window.LIB_LAZY["eusebiu-istoria#178"]=[{"v":1,"t":"Voi cita din epistola lui Dionisie către Germanus o relatare despre ce i s-a întâmplat acestuia. Vorbind despre sine, scrie astfel: Vorbesc înaintea lui Dumnezeu și El știe că nu mint. Nu am fugit din impulsul meu și nici fără îndrumare dumnezeiască."},{"v":2,"t":"Dar chiar înainte de aceasta, în însăși ora în care s-a poruncit prigoana lui Deciu, Sabin a trimis un frumentar să mă caute, iar eu am rămas acasă patru zile, așteptându-i sosirea."},{"v":3,"t":"Dar el a mers peste tot, cercetând toate locurile — drumuri, râuri și câmpuri — unde socotea că aș putea fi ascuns sau pe cale. Dar a fost lovit cu orbire și nu a găsit casa, căci nu a crezut că, fiind urmărit, voi rămâne acasă. Iar după a patra zi Dumnezeu mi-a poruncit să plec și mi-a deschis o cale în chip minunat; și am plecat împreună eu, slujitorii mei și mulți dintre frați. Și că aceasta s-a petrecut prin purtarea de grijă a lui Dumnezeu s-a arătat din cele ce au urmat, în care poate am fost de folos unora."},{"v":4,"t":"Mai departe povestește în acest chip ce i s-a întâmplat după fuga lui: „Căci spre apusul soarelui, fiind prins împreună cu cei ce erau cu mine, am fost dus de soldați la Taposiris, dar, prin purtarea de grijă a lui Dumnezeu, Timotei nu era de față și nu a fost prins. Dar venind mai târziu, a găsit casa pustie și păzită de soldați, iar pe noi reduși la robie.”"},{"v":5,"t":"După puțin spune: Și care a fost felul acelei minunate rânduieli? Căci adevărul va fi spus. Unul dintre oamenii din țară l-a întâlnit pe Timotei fugind și tulburat și l-a întrebat pricina grabei lui. Iar el i-a spus adevărul."},{"v":6,"t":"Și când omul a auzit (mergea la un ospăț de nuntă, căci era obiceiul să se petreacă toată noaptea în asemenea adunări), a intrat și a vestit celor de la masă. Iar ei, ca la un semn dinainte stabilit, s-au ridicat dintr-un singur impuls, au ieșit repede și au venit și au dat buzna peste noi cu strigăte. Îndată soldații care ne păzeau au fugit și au venit la noi, care zăceam așa cum eram pe paturile goale."},{"v":7,"t":"Dar eu, Dumnezeu știe, am crezut la început că sunt tâlhari care veniseră după pradă și jaf. Așa că am rămas pe patul pe care eram, îmbrăcat doar într-o haină de in, și le-am oferit restul hainelor mele care zăceau lângă mine. Dar ei mi-au poruncit să mă ridic și să vin repede."},{"v":8,"t":"Atunci am înțeles de ce veniseră și am strigat, rugându-i și implorându-i să plece și să ne lase în pace. Și i-am rugat, dacă vor să-mi facă vreun bine, să-i prevină pe cei ce mă duceau și să-mi taie ei înșiși capul. Și după ce am strigat astfel, după cum știu tovarășii mei și părtașii mei în toate, m-au ridicat cu de-a sila. Dar eu m-am aruncat pe spate la pământ; iar ei m-au apucat de mâini și de picioare și m-au târât."},{"v":9,"t":"Și martorii tuturor acestor întâmplări m-au urmat: Gaiu, Faust, Petru și Pavel. Dar cei care mă prinseseră m-au scos în grabă din sat și, punându-mă pe un măgar fără șa, m-au dus. Dionisie povestește acestea despre sine."}];
window.LIB_LAZY["eusebiu-istoria#179"]=[{"v":1,"t":"Același scriitor, într-o epistolă către Fabiu, episcopul Antiohiei, povestește astfel suferințele martirilor din Alexandria sub Deciu: Prigoana la noi nu a început cu porunca împărătească, ci a precedat-o cu un an întreg. Profetul și făuritorul relelor pentru această cetate, oricine a fost, a mișcat și a ațâțat mai dinainte împotriva noastră mulțimile păgânilor, reaprinzând între ei superstiția țării lor."},{"v":2,"t":"Și fiind astfel stârniți de el și găsind deplin prilej pentru orice răutate, au socotit că singura slujbă cucernică a demonilor lor este să ne omoare."},{"v":3,"t":"Au prins întâi un bătrân numit Metra și i-au poruncit să rostească cuvinte nelegiuite. Dar cum nu a vrut să asculte, l-au bătut cu ciomege, i-au sfâșiat fața și ochii cu bețe ascuțite, l-au târât afară din cetate și l-au omorât cu pietre."},{"v":4,"t":"Apoi au dus la templul idolului lor pe o femeie credincioasă, cu numele Quinta, ca să o silească să se închine. Și cum ea s-a întors cu scârbă, i-au legat picioarele și au târât-o prin toată cetatea pe străzile pavate cu piatră și au izbit-o de pietrele de moară și totodată au biciuit-o; apoi, ducând-o în același loc, au omorât-o cu pietre."},{"v":5,"t":"Apoi toți, dintr-un singur impuls, s-au repezit la casele celor cucernici și au scos afară pe oricine cunoșteau ca vecin și i-au jefuit și prădat. Au luat pentru ei averea mai de preț; dar lucrurile mai sărace și cele de lemn le-au risipit și le-au ars pe străzi, așa încât cetatea părea cucerită de un vrăjmaș."},{"v":6,"t":"Dar frații s-au retras și au plecat și „au primit cu bucurie jefuirea averii lor”, ca cei despre care Pavel a dat mărturie. Nu știu de nimeni, poate doar de vreunul care a căzut în mâinile lor, care până acum să fi tăgăduit pe Domnul."},{"v":7,"t":"Apoi au prins și pe acea minunată fecioară, Apolonia, o femeie bătrână, și, lovind-o peste fălci, i-au scos toți dinții. Și au făcut un foc în afara cetății și au amenințat că o vor arde de vie dacă nu se va alătura lor în strigătele lor nelegiuite. Iar ea, rugându-se puțin, a fost lăsată, când s-a aruncat cu râvnă în foc și a fost mistuită."},{"v":8,"t":"Apoi l-au prins pe Serapion în propria lui casă și l-au chinuit cu cruzimi aspre și, după ce i-au zdrobit toate mădularele, l-au aruncat cu capul în jos de la un etaj de sus. Și nu era niciun drum, nicio cale publică, nicio uliță deschisă pentru noi, nici noaptea, nici ziua; căci totdeauna și pretutindeni toți strigau că, dacă cineva nu va repeta cuvintele lor nelegiuite, să fie târât îndată și ars."},{"v":9,"t":"Și lucrurile au rămas astfel un timp însemnat. Dar o răscoală și un război civil au venit peste nenorocitul popor și au întors cruzimea lor față de noi unii împotriva altora. Așa am răsuflat un timp scurt, când au încetat furia împotriva noastră. Dar curând ni s-a vestit schimbarea față de acea domnie mai blândă și o mare frică de ceea ce era amenințat ne-a cuprins."},{"v":10,"t":"Căci a sosit decretul, aproape ca acel timp prea înfricoșător prevestit de Domnul nostru, care, de ar fi cu putință, ar sminti chiar pe cei aleși."},{"v":11,"t":"Toți s-au înspăimântat cu adevărat. Și mulți dintre cei mai însemnați, de frică, au ieșit îndată înainte; alții, care erau în slujba publică, erau atrași de îndatoririle lor oficiale; alții erau îndemnați de cunoscuții lor. Și, pe măsură ce li se strigau numele, se apropiau de jertfele necurate și nelegiuite. Unii dintre ei erau palizi și tremurau, ca și cum nu ar fi urmat să jertfească, ci să fie ei înșiși jertfe și prinoase pentru idoli; așa încât erau luați în râs de mulțimea care stătea împrejur, căci era vădit pentru toți că se temeau fie să moară, fie să jertfească."},{"v":12,"t":"Dar unii înaintau mai de bunăvoie la altare, declarând cu îndrăzneală că nu fuseseră niciodată creștini. Despre aceștia prevestirea Domnului nostru este foarte adevărată, că se vor mântui „cu greu”. Dintre ceilalți, unii au urmat o categorie, alții cealaltă; unii au fugit, alții au fost prinși."},{"v":13,"t":"Și dintre aceștia din urmă, unii au rămas credincioși până la lanțuri și temniță, iar unii care fuseseră chiar întemnițați multe zile au lepădat totuși credința înainte de a fi aduși la judecată. Alții, după ce au îndurat un timp chinuri mari, s-au dezis în cele din urmă."},{"v":14,"t":"Dar stâlpii tari și fericiți ai Domnului, fiind întăriți de El și primind vigoare și putere potrivite și cuvenite credinței puternice pe care o aveau, au devenit martori minunați ai Împărăției Lui."},{"v":15,"t":"Cel dintâi dintre ei a fost Iulian, un om care suferea atât de mult de gută încât nu putea nici să stea în picioare, nici să meargă. L-au adus înainte împreună cu alți doi care îl purtau. Unul dintre aceștia a tăgăduit îndată. Dar celălalt, al cărui nume era Cronion și al cărui supranume era Eunus, și bătrânul Iulian însuși, amândoi mărturisindu-l pe Domnul, au fost purtați pe cămile prin toată cetatea, care, după cum știți, este foarte mare, și în această poziție înălțată au fost bătuți și, în cele din urmă, arși într-un foc aprig, înconjurați de tot poporul."},{"v":16,"t":"Dar un soldat, numit Besas, care stătea lângă ei pe când erau duși, i-a certat pe cei care îi insultau. Și aceștia au strigat împotriva lui și acest foarte bărbătesc ostaș al lui Dumnezeu a fost dat în judecată și, făcând bine în marea luptă pentru cucernicie, a fost decapitat."},{"v":17,"t":"Un altul, libian de neam, dar cu numele și fericirea un adevărat Macar, a fost îndemnat stăruitor de judecător să se dezică; dar cum nu a cedat, a fost ars de viu. După ei, Epimah și Alexandru, rămași mult timp în lanțuri și îndurând nenumărate chinuri de la raschete și bice, au fost mistuiți și ei într-un foc aprig."},{"v":18,"t":"Și cu ei erau patru femei. Pe Ammonarion, o sfântă fecioară, judecătorul a chinuit-o fără milă și peste măsură, pentru că a declarat din început că nu va rosti nimic din ce poruncea el; și, ținându-și cu adevărat făgăduința, a fost târâtă afară. Celelalte erau Mercuria, o bătrână foarte însemnată, și Dionisia, mama multor copii, care nu și-a iubit copiii mai mult decât pe Domnul. Fiindu-i rușine guvernatorului să chinuiască astfel în zadar și fiind mereu biruit de femei, au fost omorâte prin sabie, fără încercarea chinurilor. Căci luptătoarea Ammonarion le îndurase pe acestea în numele tuturor."},{"v":19,"t":"Egiptenii Heron, Ater și Isidor, și cu ei Dioscor, un băiat de cincisprezece ani, au fost predați. La început judecătorul a încercat să amăgească pe tânăr cu vorbe frumoase, ca și cum ar fi putut fi convins ușor, apoi să-l silească prin chinuri, ca pe unul care va ceda lesne. Dar Dioscor nu a fost nici convins, nici silit."},{"v":20,"t":"Pe ceilalți, care au rămas neclintiți, i-a biciuit cu cruzime și apoi i-a dat focului. Dar admirând felul în care Dioscor se distinsese public și răspunsurile lui înțelepte la îndemnurile sale, l-a lăsat să plece, spunând că, din pricina tinereții lui, îi va da timp de pocăință. Și acest foarte cucernic Dioscor este acum printre noi, așteptând o luptă mai lungă și o încercare mai grea."},{"v":21,"t":"Dar un anume Nemesion, tot egiptean, a fost acuzat că este tovarăș de tâlhari; dar când s-a dezvinovățit înaintea sutașului de această învinuire cu totul străină de adevăr, a fost denunțat ca creștin și dus în lanțuri înaintea guvernatorului. Și acel prea nedrept judecător i-a aplicat chinuri și bătăi îndoite față de cele pe care le dădea tâlharilor și apoi l-a ars între tâlhari, cinstind astfel pe omul fericit prin asemănarea cu Hristos."},{"v":22,"t":"O ceată de soldați, Ammon, Zenon, Ptolemeu și Ingen, și cu ei un bătrân, Teofil, stăteau strânși împreună înaintea tribunalului. Și pe când o persoană judecată ca creștin părea înclinată să se dezică, ei, stând lângă ea, scrâșneau din dinți și făceau semne cu fețele și își întindeau mâinile și făceau gesturi cu trupurile. Și când atenția tuturor s-a întors spre ei, înainte ca altcineva să-i poată prinde, au alergat la tribunal spunând că sunt creștini, așa încât guvernatorul și sfatul lui s-au înspăimântat. Și cei care erau judecați se arătau foarte curajoși în așteptarea suferințelor, în timp ce judecătorii lor tremurau. Și au ieșit triumfători de la tribunal, bucurându-se de mărturia lor; însuși Dumnezeu făcându-i să biruiască în chip slăvit."}];
window.LIB_LAZY["eusebiu-istoria#180"]=[{"v":1,"t":"Mulți alții, în cetăți și sate, au fost sfâșiați de păgâni, dintre care voi pomeni unul ca ilustrare. Ischirion era folosit ca administrator de unul dintre conducători. Stăpânul lui i-a poruncit să jertfească și, la refuzul lui, l-a insultat și, cum a rămas neclintit, l-a maltratat. Și pentru că tot stăruia, a apucat un par lung și l-a străpuns prin măruntaie și l-a omorât."},{"v":2,"t":"De ce să mai vorbesc de mulțimea care a rătăcit prin deșerturi și munți și a pierit de foame, de sete, de frig, de boală, de tâlhari și de fiare sălbatice? Cei dintre ei care au rămas în viață sunt martori ai alegerii și biruinței lor."},{"v":3,"t":"Dar voi povesti o întâmplare ca exemplu. Chairemon, care era foarte bătrân, era episcopul cetății numite Nil. A fugit cu soția sa în muntele Arabiei și nu s-a mai întors. Și deși frații au căutat cu sârguință, nu i-au putut găsi nici pe ei, nici trupurile lor."},{"v":4,"t":"Și mulți care au fugit în același munte al Arabiei au fost duși în robie de sarazinii barbari. Unii dintre ei au fost răscumpărați cu greu și cu preț mare; alții nu au fost până în ziua de azi. Am povestit acestea, frate, nu fără scop, ci ca să înțelegi câte și cât de mari nevoi au venit peste noi. Cei care au avut cea mai mare experiență a lor le vor înțelege cel mai bine."},{"v":5,"t":"Puțin mai departe adaugă: Acești martiri dumnezeiești de la noi, care acum șed cu Hristos și sunt părtași ai Împărăției Lui, împărtășitori ai judecății Lui și judecători împreună cu El, au primit pe unii dintre frații care căzuseră și se făcuseră vinovați de jertfire. Când au văzut că întoarcerea și pocăința lor erau îndestulătoare ca să fie primite de Cel care nicidecum nu dorește moartea păcătosului, ci pocăința lui, încercându-i, i-au primit înapoi și i-au adunat și s-au întâlnit cu ei și au avut părtășie cu ei în rugăciuni și ospețe."},{"v":6,"t":"Ce sfat ne dați, deci, fraților, în privința unor asemenea persoane? Ce să facem? Să avem aceeași judecată și aceeași regulă ca ei și să păzim hotărârea lor și dragostea lor și să arătăm milă celor pe care ei i-au miluit? Sau să declarăm nedreaptă hotărârea lor și să ne facem judecători ai părerii lor și să întristăm mila și să răsturnăm rânduiala? Aceste cuvinte Dionisie le-a adăugat foarte potrivit când a pomenit de cei care fuseseră slabi în timpul prigoanei."}];
window.LIB_LAZY["eusebiu-istoria#181"]=[{"v":1,"t":"După aceasta, Novat, prezbiter al bisericii din Roma, fiind ridicat cu trufie împotriva acestor persoane, ca și cum nu mai era pentru ele nădejde de mântuire, nici dacă ar face toate cele ce țin de o convertire adevărată și curată, a devenit căpetenia ereziei celor care, în mândria închipuirii lor, se numesc catari."},{"v":2,"t":"Atunci s-a adunat la Roma un sinod foarte mare, de episcopi în număr de șaizeci și mult mai mulți prezbiteri și diaconi; în timp ce păstorii celorlalte provincii se sfătuiau în locurile lor, în privat, asupra a ce trebuia făcut. S-a întărit de toți o hotărâre: Novat și cei care s-au alăturat lui și cei care au îmbrățișat părerea lui, vrăjmașă fraților și neomenoasă, să fie socotiți de Biserică străini; dar să vindece pe acei frați care căzuseră în nenorocire și să le slujească cu leacurile pocăinței."},{"v":3,"t":"Au ajuns la noi epistole ale lui Corneliu, episcopul Romei, către Fabiu al bisericii din Antiohia, care arată ce s-a făcut la sinodul din Roma și ce a părut mai bine tuturor celor din Italia, Africa și regiunile din jur. De asemenea, alte epistole, scrise în limba latină, ale lui Ciprian și ale celor împreună cu el din Africa, care arată că erau de acord în privința nevoii de a ajuta pe cei ispitiți și de a tăia din Biserica Catolică pe căpetenia ereziei și pe toți cei ce s-au alăturat lui."},{"v":4,"t":"O altă epistolă a lui Corneliu, privind hotărârile sinodului, este atașată acestora; și încă altele, despre purtarea lui Novat, din care este potrivit să facem selecții, ca oricine vede această lucrare să știe despre el."},{"v":5,"t":"Corneliu îl face cunoscut lui Fabiu pe Novat, ce fel de om era, în aceste cuvinte: Dar ca să știți că de mult timp acest om remarcabil dorea episcopia, dar a ținut pentru sine această dorință ambițioasă și a ascuns-o — folosind drept acoperământ pentru răzvrătirea lui pe acei mărturisitori care se lipiseră de el de la început — doresc să vorbesc."},{"v":6,"t":"Maxim, unul dintre prezbiterii noștri, și Urban, care de două ori a dobândit cea mai înaltă cinste prin mărturisire, cu Sidoniu și Celerin, un om care prin harul lui Dumnezeu a îndurat cu cea mai mare vitejie toate felurile de chin și prin tăria credinței sale a biruit slăbiciunea cărnii și a învins cu putere pe potrivnic — acești oameni l-au descoperit și i-au dat în vileag viclenia și fățărnicia, jurămintele false și minciunile, nesociabilitatea și prietenia cruntă. Și s-au întors la sfânta biserică și au vestit în fața multora, atât episcopi și prezbiteri, cât și un mare număr de mireni, toată viclenia și răutatea lui, pe care mult timp o ascunsese. Și au făcut aceasta cu tânguiri și pocăință, pentru că prin îndemnurile fiarei viclene și răutăcioase părăsiseră pentru un timp biserica. Puțin mai departe spune:"},{"v":7,"t":"Cât de remarcabilă, iubite frate, este schimbarea și prefacerea pe care am văzut-o petrecându-se în el într-un timp scurt. Căci acest om prea strălucit, care se legase cu jurăminte cumplite să nu caute în niciun chip episcopia, apare deodată episcop, ca aruncat între noi printr-o mașinărie."},{"v":8,"t":"Căci acest dogmatist, acest apărător al învățăturii Bisericii, încercând să apuce și să ia episcopia, care nu-i fusese dată de sus, a ales doi dintre tovarășii lui care își părăsiseră propria lor mântuire. Și i-a trimis într-un colț mic și neînsemnat al Italiei, ca acolo, printr-un argument fals, să înșele trei episcopi, care erau oameni de la țară și foarte simpli. Și aceștia au afirmat cu hotărâre și tărie că trebuie să vină repede la Roma, pentru ca toată dezbinarea care se ridicase acolo să fie potolită prin mijlocirea lor, împreună cu alți episcopi."},{"v":9,"t":"Când au venit, fiind, după cum am spus, foarte simpli în viclenia și meșteșugul celor răi, au fost închiși cu anume oameni aleși, ca el. Și pe la ceasul al zecelea, când se îmbătaseră și se simțeau rău, i-a silit cu de-a sila să-i dea episcopia printr-o punere falsă și zadarnică a mâinilor. Pentru că nu i-a venit, s-a răzbunat prin viclenie și trădare."},{"v":10,"t":"Unul dintre acești episcopi s-a întors în scurt timp la biserică, tânguindu-se și mărturisindu-și greșeala. Și l-am primit la împărtășanie ca pe un mirean, tot poporul de față mijlocind pentru el. Iar în locul celorlalți episcopi am hirotonit urmași și i-am trimis în locurile unde erau ei."},{"v":11,"t":"Acest răzbunător al Evangheliei nu știa, deci, că într-o biserică catolică trebuie să fie un singur episcop; totuși nu știa (căci cum ar fi putut?) că în ea erau patruzeci și șase de prezbiteri, șapte diaconi, șapte subdiaconi, patruzeci și doi de acoliți, cincizeci și doi de exorciști, citeți și portari, și peste o mie cinci sute de văduve și persoane în nevoie, pe toți aceștia îi hrănesc harul și bunătatea Stăpânului."},{"v":12,"t":"Dar nici această mare mulțime, atât de necesară în biserică, nici cei care, prin purtarea de grijă a lui Dumnezeu, erau bogați și îndestulați, împreună cu foarte mulții, ba nenumărații oameni, nu l-au putut întoarce de la o asemenea deznădejde și îndrăzneală și să-l cheme înapoi la Biserică."},{"v":13,"t":"Iarăși, mai departe, adaugă aceste cuvinte: Îngăduiți-ne să spunem mai departe: Din pricina căror lucrări sau purtări a avut încrederea să lupte pentru episcopie? Pentru că fusese crescut în Biserică de la început și îndurase multe lupte pentru ea și trecuse prin multe și mari primejdii pentru religie? Cu adevărat nu aceasta este faptul."},{"v":14,"t":"Ci Satan, care a intrat și a locuit în el multă vreme, a fost prilejul credinței lui. Fiind scăpat de exorciști, a căzut într-o boală grea; și, părând că e gata să moară, a primit botezul prin turnare, pe patul pe care zăcea; dacă într-adevăr putem spune că un astfel de om l-a primit."},{"v":15,"t":"Și când s-a vindecat de boală, nu a primit celelalte lucruri care trebuie avute după canonul Bisericii, anume pecetluirea de către episcop. Și neprimind aceasta, cum ar fi putut primi Duhul Sfânt?"},{"v":16,"t":"Puțin mai încolo spune din nou: „În vremea prigoanei, din lașitate și iubire de viață, a tăgăduit că ar fi prezbiter. Căci atunci când a fost rugat și implorat de diaconi să iasă din odaia în care se închisese și să dea ajutor fraților, pe cât era îngăduit și cu putință unui prezbiter, să ajute pe acei frați care se aflau în primejdie și aveau nevoie de ajutor, a luat atât de puțin în seamă rugămințile diaconilor, încât a plecat și s-a dus mâniat. Căci spunea că nu mai dorește să fie prezbiter, fiind un admirator al altei filozofii.”"},{"v":17,"t":"Trecând peste câteva lucruri, adaugă următoarele: „Căci acest om strălucit a părăsit Biserica lui Dumnezeu, în care, când a crezut, a fost găsit vrednic de prezbiterat prin bunăvoința episcopului care l-a hirotonit în slujba prezbiterală. Aceasta fusese împotrivită de tot clerul și de mulți dintre mireni; pentru că era nepermis ca unul care fusese stropit pe patul lui din pricina bolii, cum fusese el, să intre în vreo slujbă clericală; dar episcopul a cerut să i se îngăduie să-l hirotonească doar pe acesta.”"},{"v":18,"t":"La acestea adaugă încă una, cea mai rea dintre toate greșelile omului, astfel: Căci atunci când a făcut aducerile și împarte o parte fiecăruia, pe când o dă, îl silește pe nenorocit să jure în locul binecuvântării. Ținându-i mâinile în ambele ale lui, nu-l lasă până nu a jurat în acest chip (căci voi da propriile lui cuvinte): «Jură-mi pe trupul și sângele Domnului nostru Isus Hristos că nu mă vei părăsi niciodată și nu te vei întoarce la Corneliu.»"},{"v":19,"t":"Și nefericitul nu gustă până nu a chemat blesteme asupra lui; și în loc să spună Amin, când ia pâinea, spune: Nu mă voi întoarce niciodată la Corneliu. Mai departe spune iarăși:"},{"v":20,"t":"„Dar să știți că acum a rămas gol și pustiu; căci frații îl părăsesc în fiecare zi și se întorc la biserică. Și Moise, fericitul martir, care a suferit de curând între noi un martiriu slăvit și minunat, pe când încă trăia, văzându-i îndrăzneala și nebunia, a refuzat să se împărtășească cu el și cu cei cinci prezbiteri care s-au despărțit împreună cu el de biserică.”"},{"v":21,"t":"La încheierea scrisorii sale dă o listă a episcopilor care veniseră la Roma și condamnaseră nebunia lui Novat, cu numele lor și parohia pe care o păstorea fiecare dintre ei."},{"v":22,"t":"Pomenește și pe cei care nu au venit la Roma, dar și-au exprimat prin scrisori învoirea cu votul acestor episcopi, dând numele lor și cetățile din care le-au trimis fiecare. Acestea le-a scris Corneliu lui Fabiu, episcopul Antiohiei."}];
window.LIB_LAZY["eusebiu-istoria#182"]=[{"v":1,"t":"Aceluiași Fabiu, care părea să încline oarecum spre această schismă, i-a scris o epistolă și Dionisie al Alexandriei. Scrie în ea multe alte lucruri despre pocăință și povestește luptele celor care suferiseră de curând martiriul la Alexandria. După cealaltă relatare, pomenește un anumit fapt minunat, care merită un loc în această lucrare. Este următorul:"},{"v":2,"t":"Vă voi da acest singur exemplu petrecut la noi. Era la noi un anume Serapion, un credincios bătrân, care trăise multă vreme fără vină, dar căzuse în încercare. Se ruga adesea, dar nimeni nu-l lua în seamă, pentru că jertfise. Dar s-a îmbolnăvit și trei zile la rând a rămas fără glas și fără simțire."},{"v":3,"t":"Revenindu-și oarecum în ziua a patra, a trimis după nepotul său de fiică și i-a zis: Cât mă mai ții, copilul meu? Te rog, grăbește-te și dezleagă-mă repede. Cheamă-mi pe unul dintre prezbiteri. Și după ce a spus aceasta, a rămas din nou fără glas. Iar băiatul a alergat la prezbiter. Dar era noapte, iar acesta era bolnav și deci nu putea veni."},{"v":4,"t":"Dar fiindcă poruncisem ca persoanele aflate în pragul morții, dacă o cer, și mai ales dacă o ceruseră mai dinainte, să primească iertarea, ca să plece cu bună nădejde, i-a dat băiatului o mică parte din euharistie, spunându-i să o muieze și să lase picăturile să cadă în gura bătrânului."},{"v":5,"t":"Băiatul s-a întors cu ea și, pe când se apropia, înainte de a intra, Serapion, trezindu-se din nou, a zis: «Ai venit, copilul meu, iar prezbiterul nu a putut veni; dar fă repede ce ți-a poruncit și lasă-mă să plec.» Atunci băiatul a muiat-o și a picurat-o în gura lui. Și după ce a înghițit puțin, îndată și-a dat duhul."},{"v":6,"t":"Nu este vădit că a fost păstrat și viața lui a continuat până a fost dezlegat și, păcatul lui fiind șters, a putut fi recunoscut pentru multele fapte bune pe care le făcuse? Dionisie povestește acestea."}];
window.LIB_LAZY["eusebiu-istoria#183"]=[{"v":1,"t":"Dar să vedem cum i s-a adresat același om lui Novat când tulbura frăția romană. Pentru că el se prefăcea că unii dintre frați au fost prilejul apostaziei și schismei lui, ca și cum ar fi fost silit de ei să procedeze cum a procedat, observați felul în care îi scrie:"},{"v":2,"t":"„Dionisie fratelui său Novat, salutare. Dacă, după cum spui, ai fost dus fără voia ta, vei dovedi aceasta dacă te vei retrage de bunăvoie. Căci mai bine ar fi să sufere cineva totul, decât să dezbine Biserica lui Dumnezeu. Chiar martiriul pentru a împiedica dezbinarea nu ar fi mai puțin slăvit decât cel pentru a refuza închinarea la idoli. Ba mie mi se pare mai mare. Căci într-un caz omul suferă martiriul pentru propriul său suflet; în celălalt, în folosul întregii Biserici. Și acum, dacă poți convinge sau îndupleca pe frați să vină la unanimitate, dreptatea ta va fi mai mare decât greșeala ta și aceasta nu va fi socotită, iar acea dreptate va fi lăudată. Dar dacă nu poți birui pe cei neascultători, cel puțin mântuiește-ți sufletul tău. Mă rog să te porți bine, păstrând pacea în Domnul.” Aceasta i-a scris lui Novat."}];
window.LIB_LAZY["eusebiu-istoria#184"]=[{"v":1,"t":"A scris și o epistolă către frații din Egipt, Despre pocăință. În ea înfățișează ce i s-a părut potrivit în privința celor care căzuseră și descrie categoriile de greșeli."},{"v":2,"t":"Se păstrează și o scrisoare privată Despre pocăință, pe care a scris-o lui Conon, episcopul parohiei din Hermopole, și alta cu caracter de îndemn, către turma sa din Alexandria. Printre ele este și cea scrisă lui Origen Despre martiriu și frațiilor din Laodiceea, al căror episcop era Telimidre. A trimis tot astfel una Despre pocăință frații din Armenia, al căror episcop era Merozan."},{"v":3,"t":"Pe lângă toate acestea, a scris lui Corneliu al Romei, când primise de la el o epistolă împotriva lui Novat. Spune în ea că fusese invitat de Helen, episcopul Tarsului din Cilicia, și de ceilalți care erau cu el, Firmilian, episcop în Capadocia, și Teoctist, din Palestina, să se întâlnească cu ei la sinodul din Antiohia, unde unele persoane se străduiau să întemeieze schisma lui Novat."},{"v":4,"t":"Pe lângă aceasta, scrie că i se spusese că Fabiu adormise și că Demetrian fusese rânduit urmașul lui în episcopia Antiohiei. Scrie de asemenea în aceste cuvinte despre episcopul Ierusalimului: „Căci fericitul Alexandru, fiind închis în temniță, a trecut fericit.”"},{"v":5,"t":"În afară de aceasta, se păstrează și o altă epistolă diaconală a lui Dionisie, trimisă celor din Roma prin Ipolit. Și le-a scris alta Despre pace, tot astfel Despre pocăință; și încă una mărturisitorilor de acolo care mai țineau încă părerea lui Novat. A trimis încă două acelorași persoane după ce se întorseseră la Biserică. Și a ținut legătura cu mulți alții prin scrisori, pe care le-a lăsat în urmă ca un folos, în diferite chipuri, pentru cei care își studiază acum cu sârguință scrierile."}];
